/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A30 frozen manifest: engraving–escutcheon (80 headwords), hand-authored. */
'use strict';
const D = globalThis.RA.D;
const Q = (w,n,s,p,a,b,c,x,type='meaning') => ({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:type,type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M = (wrong,right,reason,type='meaning') => ({errorType:type,wrong,right,reason});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E = (origin,w) => ({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P = (w,origin,ctx,mistake,quiz) => D(w,{etymology:E(origin,w),contexts:[ctx],mistakes:[mistake],quiz});

P('engraving','engraving 是 engrave 加名词后缀 -ing；engrave 经古法语 engraver 进入英语，表示刻入表面。',C('engraving.s1','版画','The curator chose an engraving of the harbor because its carefully cut lines showed details that a broad watercolor could not capture.','策展人选了一幅港口版画，因为细致的刻线呈现了大幅水彩难以表现的细节。','The curator chose an engraving of the harbor / because its carefully cut lines showed details / that a broad watercolor could not capture.','可数义指一幅版画；也可指雕刻技艺。','作品由刻线制成，符合 engraving 的版画义。'),M('The gallery labeled a hand-painted watercolor as an engraving.','The gallery labeled a hand-painted watercolor as a watercolor.','手绘水彩不是由刻版制成的 engraving；改成 watercolor 即纠正标签。'),[Q('engraving',1,1,'An engraving is most directly connected with?','a design cut into a surface or printed from a plate','a song recorded live','a clay pot shaped without decoration','engraving 指刻入表面的图案，也指由雕版印出的图像。'),Q('engraving',2,1,'Why might a museum display an engraving beside its copper plate?','The print may have been made from that engraved plate.','The plate is the sound recording for the image.','The plate is a later frame for a watercolor.','版画可由刻有图案的铜版印制。'),Q('engraving',3,1,'Which phrase uses engraving naturally?','a finely detailed engraving','an engraving of boiling soup','an engraving who arrived late','engraving 可以指精细刻制或印出的图像。'),Q('engraving',4,1,'In an art catalogue, “an engraving by Lee” most likely means?','a print Lee made using an engraved plate','a list of Lee’s appointments','a sculpture Lee carved from ice','艺术目录中 engraving 通常指雕版印刷作品。')]);
P('engrossed','engrossed 是 engross 的过去分词形容词；engross 经中古英语进入，现代常见义是占据某人的全部注意力。',C('engrossed.s1','阅读','Mina was so engrossed in the field notes that she failed to hear the train announcement and had to ask a conductor where to get off.','米娜全神贯注地看野外笔记，没听见列车广播，只好问乘务员在哪站下车。','Mina was so engrossed in the field notes / that she failed to hear the train announcement / and had to ask a conductor where to get off.','常用 be engrossed in + 名词或动名词；描述投入的人。','她因专注笔记而没听广播，体现 engrossed 的义项。'),M('The engrossed reader kept interrupting the book every few seconds to watch the clock.','The distracted reader kept interrupting the book every few seconds to watch the clock.','频繁转去看时钟表现分心，和 engrossed 的全神贯注相反。'),[Q('engrossed',1,1,'Someone engrossed in a book is?','giving it nearly all their attention','looking for a bookshop','trying to sell the book','engrossed in 表示注意力全放在某事上。'),Q('engrossed',2,1,'Choose the natural completion: “The child was engrossed ___ the puzzle.”','in','at','from','固定搭配是 be engrossed in。'),Q('engrossed',3,1,'Which scene best fits “engrossed”?','A reader misses the dinner bell while following a novel.','A reader checks the time every minute.','A reader closes the book without opening it.','投入阅读以致没注意铃声，是全神贯注。'),Q('engrossed',4,1,'“She was engrossed in the repair” describes?','her intense concentration on the repair','her dislike of repairing things','her uncertainty about the repair cost','该形容词描述注意力被修理工作完全吸引。')]);
P('engrossing','engrossing 是 engross 加 -ing 构成的形容词，指能吸引并占据注意力的事物。',C('engrossing.s1','故事','The documentary became engrossing once the researchers found a second set of tracks, each leading toward the same hidden valley.','研究人员发现第二组足迹后，这部纪录片变得引人入胜；两组足迹都通向同一座隐蔽山谷。','The documentary became engrossing / once the researchers found a second set of tracks / each leading toward the same hidden valley.','-ing 形容词描述事物造成的效果；常与 story、book、film 搭配。','纪录片让观众想持续关注，因此是 engrossing。'),M('The engrossing lecture lost the audience because everyone found it impossible to stay interested.','The dull lecture lost the audience because everyone found it impossible to stay interested.','观众无法保持兴趣说明 lecture 枯燥，而非引人入胜。'),[Q('engrossing',1,1,'An engrossing film is one that?','holds the viewer’s attention','has no story or images','is shown only to its director','engrossing 表示非常吸引人、使人专注。'),Q('engrossing',2,1,'Which description fits an engrossing mystery?','Readers keep turning pages to learn what happened.','Readers forget that they opened it.','Readers stop because every page is blank.','读者急于知道后续，说明故事吸引注意。'),Q('engrossing',3,1,'Choose the closest meaning of “an engrossing account.”','a fascinating account','a barely readable account','a strictly numerical account','engrossing 可用 fascinating 表达“引人入胜的”。'),Q('engrossing',4,1,'The speaker gave an engrossing talk, so listeners were likely to?','follow it closely until the end','leave because it held no interest','ignore every point from the start','引人入胜的演讲会让听众持续关注。')]);
P('enhancement','enhancement 由 enhance 加 -ment 构成；enhance 经古法语进入英语，常指质量、价值或效果的提升。',C('enhancement.s1','图像处理','The software offers an enhancement that sharpens faint labels in scanned maps without changing the original file stored by the archive.','该软件提供一种增强功能，可让扫描地图上模糊的标注变清晰，同时不更改档案馆保存的原始文件。','The software offers an enhancement / that sharpens faint labels in scanned maps / without changing the original file stored by the archive.','enhancement 是可数名词，可指一次改进或增强功能。','使标签更清晰是质量提升，符合 enhancement。'),M('The update was an enhancement because it removed the feature users had requested and made the display harder to read.','The update was not an enhancement because it removed the feature users had requested and made the display harder to read.','删除用户需要的功能且降低可读性并非改进；加 not 即纠正判断。'),[Q('enhancement',1,1,'A software enhancement is usually?','an improvement to how the software works','a record of its original errors','a plan to stop all future updates','enhancement 指质量、性能或价值的提高。'),Q('enhancement',2,1,'Adding captions that make a video accessible is an?','enhancement','enclosure','enchantment','提升视频可访问性的功能属于改进。'),Q('enhancement',3,1,'Which phrase is most natural?','image enhancement','image enhanceness','image enhancedment','image enhancement 是常用名词搭配。'),Q('enhancement',4,1,'A lighting enhancement in a theater would aim to?','improve the audience’s view of the stage','remove every light from the building','change the play into a written exam','灯光增强旨在改善舞台呈现或观看效果。')]);
P('enhancer','enhancer 由 enhance 加施事/工具后缀 -er 构成，指增强效果的物质或因素。',C('enhancer.s1','食品科学','The laboratory compared each flavor enhancer with an untreated sample to see whether it made the soup taste stronger without adding excess salt.','实验室将每种增味剂与未处理样品比较，确认它能否在不过量加盐的情况下增强汤的味道。','The laboratory compared each flavor enhancer with an untreated sample / to see whether it made the soup taste stronger / without adding excess salt.','enhancer 可指物质或其他能增强效果的因素；此处为可数名词。','物质使味道更浓，直接体现 enhancer 的作用。'),M('The flavor enhancer weakened the taste so thoroughly that the soup became less flavorful.','The flavor reducer weakened the taste so thoroughly that the soup became less flavorful.','削弱味道的物质是 reducer；enhancer 应增强效果。'),[Q('enhancer',1,1,'A flavor enhancer is added to?','make a food’s flavor more noticeable','remove all flavor from food','measure the temperature of a meal','enhancer 是加强效果的物质或因素。'),Q('enhancer',2,1,'A contrast enhancer in an image editor would?','make light and dark areas more distinct','erase every pixel in the image','translate the captions into speech','contrast enhancer 用于增强明暗对比。'),Q('enhancer',3,1,'Which item could be called an enhancer?','a factor that strengthens a medicine’s effect','a device that turns a phone off','a label listing the medicine’s price','能加强药效的因素可称作 enhancer。'),Q('enhancer',4,1,'The word enhancer names something that?','increases the strength of an effect','makes an effect disappear','describes an effect without changing it','-er 在此表示起增强作用的物质或因素。')]);
P('enigmatic','enigmatic 来自希腊语 ainigma“谜语”，经拉丁语和法语进入英语，形容难以理解或解释的事物。',C('enigmatic.s1','艺术','The painter left an enigmatic note beside the unfinished portrait, giving the conservator no clear clue about the sitter’s identity.','画家在未完成的肖像旁留下一张晦涩的便条，修复师无法据此明确判断画中人的身份。','The painter left an enigmatic note beside the unfinished portrait / giving the conservator no clear clue / about the sitter’s identity.','enigmatic 修饰人、表情、信息等难以解释的对象。','便条没有提供可解读的线索，故称 enigmatic。'),M('The instructions were enigmatic: every step was explained plainly, and no reader could misunderstand them.','The instructions were explicit: every step was explained plainly, and no reader could misunderstand them.','清晰易懂的说明是 explicit；enigmatic 意味着费解。'),[Q('enigmatic',1,1,'An enigmatic smile is?','difficult to interpret','impossible to see','clearly explained in words','enigmatic 表示神秘、难以理解。'),Q('enigmatic',2,1,'A witness gives an enigmatic reply when it?','leaves the questioner unsure what the witness means','states a clear date and place','repeats the question exactly','含糊难解的回答无法让提问者确定意思。'),Q('enigmatic',3,1,'Choose the closest opposite of enigmatic.','straightforward','cryptic','mysterious','straightforward 表示直截了当，与费解相反。'),Q('enigmatic',4,1,'Which object is most likely to be called enigmatic?','a symbol whose meaning no one can identify','a timetable with every stop listed','a label naming the contents of a jar','无人能辨明的符号具有难解特征。')]);
P('enlargement','enlargement 由 enlarge 加 -ment 构成；除“扩大”外，也指放大的照片或图像。',C('enlargement.s2','摄影','The photographer ordered an enlargement of the family portrait so that the small inscriptions on the framed certificates would be legible.','摄影师订制了一张家庭肖像的放大照片，以便看清相框证书上的小字。','The photographer ordered an enlargement of the family portrait / so that the small inscriptions / on the framed certificates would be legible.','义项 s2 可数，指放大的照片；enlargement of + 图像/照片。','订制大尺寸照片对应 enlargement 的摄影义。'),M('The photographer requested an enlargement but received a print half the size of the original.','The photographer requested a reduction but received a print half the size of the original.','比原件更小的是缩印 reduction，不是放大 enlargement。'),[Q('enlargement',1,2,'In a photo shop, an enlargement is?','a print made bigger than the original','a smaller copy for a passport','a list of camera settings','摄影义的 enlargement 是放大的照片。'),Q('enlargement',2,1,'The enlargement of a doorway would make it?','wider or larger','invisible','a photograph','普通义 enlargement 指扩大尺寸。'),Q('enlargement',3,2,'Why order an enlargement of a small map?','to see its details more easily','to make the map smaller','to remove all place names','放大地图便于看清细节。'),Q('enlargement',4,1,'Which sentence uses enlargement in the size-change sense?','The doorway’s enlargement allowed a wheelchair through.','Her enlargement displayed the wedding photograph.','The enlargement was a menu listing prices.','此处表示 doorway 扩大，符合 s1。')]);
P('enlightenment','enlightenment 由 enlighten 加 -ment 构成，常指知识带来的开明、领悟，也可指历史上的启蒙思潮。',C('enlightenment.s1','科学学习','A short course in astronomy brought enlightenment to the class, which had previously mistaken the phases of the Moon for Earth’s shadow.','一门简短的天文学课程让全班豁然开朗；此前他们一直把月相误认为地球的影子。','A short course in astronomy brought enlightenment to the class / which had previously mistaken the phases of the Moon / for Earth’s shadow.','bring enlightenment to someone 表示使其获得理解或启发。','课程纠正错误认识、带来清楚理解，体现此义。'),M('The lesson brought enlightenment by leaving every student more confused about the subject.','The lesson brought confusion by leaving every student more confused about the subject.','让学生更困惑不是 enlightenment；confusion 才符合结果。'),[Q('enlightenment',1,1,'A moment of enlightenment is when someone?','suddenly understands something more clearly','forgets the subject completely','turns off every light in a room','抽象义 enlightenment 指理解加深或豁然领悟。'),Q('enlightenment',2,1,'Which class activity might bring enlightenment about astronomy?','explaining why the Moon has phases','covering the telescope lens','memorizing unrelated lunch orders','解释月相成因能增进理解。'),Q('enlightenment',3,1,'In European history, the Enlightenment was associated with?','reason, learning, and new ideas','the invention of moving stairs','the end of all written debate','历史上的启蒙运动推崇理性与知识。'),Q('enlightenment',4,1,'The guide’s explanation gave the visitor enlightenment about the ruins. The visitor?','understood the ruins better','became unable to see the ruins','received a new building permit','此处表示通过解释增进理解。')]);
P('enmity','enmity 由古法语 enemi“敌人”相关词形演变而来，现指持久而强烈的敌意。',C('enmity.s1','政治','Years of enmity between the neighboring councils eased only after both agreed to share the river data and meet each month.','两个相邻委员会之间多年的敌意，直到双方同意共享河流数据并每月会谈后才有所缓和。','Years of enmity between the neighboring councils eased / only after both agreed to share the river data / and meet each month.','enmity 通常不可数，常与 between、toward 搭配。','长期对立并经协商缓和，说明这是持久敌意。'),M('Their enmity disappeared because they had never disagreed and trusted each other completely.','Their friendship flourished because they had never disagreed and trusted each other completely.','从未争执且完全信任表示友好关系，不是 enmity。'),[Q('enmity',1,1,'Enmity between two groups means?','deep hostility between them','a short shared vacation','a formal agreement to cooperate','enmity 指强烈、持续的敌对。'),Q('enmity',2,1,'Which event is most likely to reduce enmity?','the former rivals agree to resolve disputes through talks','one side spreads more threats','the groups refuse to communicate','对话有机会缓和长期敌意。'),Q('enmity',3,1,'Choose the closest opposite of enmity.','friendship','hostility','antagonism','friendship 与敌意相反。'),Q('enmity',4,1,'A historian describes “centuries of enmity.” This suggests?','a long-lasting hostile relationship','a single friendly greeting','a brief disagreement over lunch','centuries of 表明敌意延续很久。')]);
P('ennui','ennui 借自法语 ennui，最终与拉丁语 inodiare“使令人厌烦”相关，指倦怠、无聊和不满足。',C('ennui.s1','日常生活','After weeks of identical shifts and no time outdoors, the crew felt ennui and began planning small changes to their routine.','连续几周轮班一成不变、又没有户外时间后，船员们感到倦怠，开始计划对日常安排做些小改变。','After weeks of identical shifts and no time outdoors / the crew felt ennui / and began planning small changes to their routine.','ennui 作不可数名词，语气较正式，强调乏味带来的倦怠感。','单调生活引发的不满和厌倦符合 ennui。'),M('The crew felt ennui because each day was thrilling, varied, and full of new challenges.','The crew felt excitement because each day was thrilling, varied, and full of new challenges.','充满刺激和变化应产生 excitement，而非倦怠。'),[Q('ennui',1,1,'A person suffering from ennui feels?','bored and dissatisfied','surprised by a sudden gift','angry about a broken bone','ennui 指倦怠、无聊与不满足。'),Q('ennui',2,1,'Which routine is most likely to produce ennui?','repeating the same dull task for weeks','learning a new skill each morning','traveling through unfamiliar places','长时间重复单调工作容易带来倦怠。'),Q('ennui',3,1,'Which word is closest to ennui?','weariness','delight','urgency','weariness 接近倦怠之意。'),Q('ennui',4,1,'The novel’s hero escapes ennui by?','finding a meaningful new project','doing the same empty task forever','refusing every new experience','有意义的新活动能打破无聊倦怠。')]);
P('enormity','enormity 源自拉丁语 enormitas“偏离常规、巨大”，现代常指罪行的极端恶劣或事件的惊人规模。',C('enormity.s1','灾害报道','The report conveyed the enormity of the flood by comparing the submerged district with the size of the entire old town.','报告把被淹地区与整座老城作比较，呈现出洪水规模之惊人。','The report conveyed the enormity of the flood / by comparing the submerged district / with the size of the entire old town.','此义为不可数名词，常见 the enormity of + 事件。','用巨大范围体现事件规模，对应 s1 的“惊人严重程度/规模”。'),M('The enormity of the minor scratch shocked the town, although it needed no treatment and caused no damage.','The triviality of the minor scratch shocked the town, although it needed no treatment and caused no damage.','无损伤的小擦痕并不巨大严重；triviality 才符合轻微程度。'),[Q('enormity',1,1,'“The enormity of the disaster” refers to?','its shocking scale or seriousness','the exact time it began','the number of reporters present','enormity 可表示事件规模或严重程度惊人。'),Q('enormity',2,1,'Which act might be condemned for its enormity?','a grave crime causing immense harm','a harmless spelling mistake','a routine change of office hours','严重造成巨大伤害的罪行可称极其恶劣。'),Q('enormity',3,1,'In careful usage, enormity is best matched with?','the enormity of the loss','the enormity of a tiny improvement','the enormity of a teaspoon’s handle','常与重大损失或灾害规模搭配。'),Q('enormity',4,1,'The enormity of the task became clear when the team saw?','how many years of records had to be checked','that the task was a one-minute note','that no work remained','工作量巨大体现任务的规模。')]);
P('enormously','enormously 是 enormous 加副词后缀 -ly，表示程度极大。',C('enormously.s1','城市发展','The new bridge enormously reduced the detour for villages on the east bank, making daily deliveries far cheaper.','新桥大幅缩短了东岸村庄的绕行路程，使日常配送便宜得多。','The new bridge enormously reduced the detour / for villages on the east bank / making daily deliveries far cheaper.','副词修饰 reduced，强调变化幅度非常大。','绕行大幅缩短，符合 enormously 的程度义。'),M('The bridge enormously reduced the detour by adding just one extra mile to every trip.','The bridge slightly reduced the detour by adding just one extra mile to every trip.','增加一英里且变化很小，不应说 enormously；slightly 符合小幅变化。'),[Q('enormously',1,1,'If a cost rises enormously, it rises?','by a very large amount','in a perfectly steady line','for no measurable amount','enormously 表示程度或幅度极大。'),Q('enormously',2,1,'Which sentence uses enormously naturally?','The new evidence enormously changed the investigation.','She enormously placed the cup on the table.','They enormously arrived at noon.','该副词适合修饰变化或影响程度。'),Q('enormously',3,1,'Choose the closest meaning of “enormously useful.”','extremely useful','slightly useful','not useful at all','enormously useful 表示极其有用。'),Q('enormously',4,1,'A machine that enormously speeds production?','makes production much faster','makes no difference to speed','stops production permanently','enormously 修饰速度提升，表示大幅加快。')]);
P('enquiry','enquiry 与 inquire 同源，源于古法语 enquerre 和拉丁语 inquirere“探问、调查”；英式拼法 enquiry 常用于询问或正式调查。',C('enquiry.s1','客户服务','The museum received an enquiry about wheelchair access, so a staff member sent the visitor a floor plan and lift details.','博物馆收到一项关于轮椅通行的询问，于是工作人员给访客发去楼层图和电梯信息。','The museum received an enquiry about wheelchair access / so a staff member sent the visitor a floor plan / and lift details.','enquiry 可数，常用 an enquiry about + 主题；拼法 enquiry 常见于英式英语。','访客询问通行信息，体现“询问”义。'),M('The visitor made an enquiry but asked no question and requested no information.','The visitor made no enquiry and requested no information.','没有提出问题或索要信息就没有进行 enquiry；删除矛盾的 an enquiry。'),[Q('enquiry',1,1,'A customer enquiry is?','a request for information','a final payment receipt','a building’s emergency exit','enquiry 指询问或信息请求。'),Q('enquiry',2,1,'A formal enquiry into an accident would?','investigate how the accident happened','advertise the next public event','repair the damaged road without examining it','正式 enquiry 可以指调查事故经过。'),Q('enquiry',3,1,'Which phrase is natural?','make an enquiry about opening hours','make an enquiry the window','do enquiry to opening hours','常用 make an enquiry about。'),Q('enquiry',4,1,'In British spelling, enquiry is related to the verb?','inquire','inquirement','inquisitionary','enquiry 与 inquire 同源，常指询问。')]);
P('enrage','enrage 由 en-“使进入某状态”与 rage“狂怒”构成，意思是使某人非常愤怒。',C('enrage.s1','公共事务','The unexplained cancellation of the hearing enraged residents, who had travelled for hours to present evidence about the contaminated well.','听证会被无故取消，令居民十分愤怒；他们已经长途跋涉赶来提交有关水井污染的证据。','The unexplained cancellation of the hearing enraged residents / who had travelled for hours / to present evidence about the contaminated well.','enrage 是及物动词，宾语是被激怒的人；过去式 enraged。','取消听证会使居民发怒，体现使人愤怒。'),M('The unexplained cancellation enraged the residents, who were pleased and completely untroubled by it.','The unexplained cancellation surprised the residents, who were pleased and completely untroubled by it.','高兴且不受困扰的人并未被激怒；surprised 可保留意外反应。'),[Q('enrage',1,1,'To enrage someone is to make that person?','extremely angry','sleepy after lunch','certain about a measurement','enrage 表示激怒。'),Q('enrage',2,1,'Which action could enrage a customer?','charging an unexplained fee after promising a free service','answering a question politely','sending the promised receipt','违背免费承诺并乱收费可能激怒顾客。'),Q('enrage',3,1,'Choose the correct form: “The decision ___ the residents.”','enraged','enragely','enragingly','过去事件作主语时可用及物过去式 enraged。'),Q('enrage',4,1,'A remark that enrages a listener?','makes the listener furious','helps the listener relax','gives the listener a map','enrage 的结果是愤怒。')]);
P('enrapture','enrapture 由 en- 与 rapture“狂喜、入迷”构成，意为使某人极为愉悦或着迷。',C('enrapture.s1','音乐','The violin solo enraptured the audience, whose members remained silent until the final note faded and then rose to applaud.','小提琴独奏令观众陶醉；最后一个音符消散后，他们才安静地起身鼓掌。','The violin solo enraptured the audience / whose members remained silent / until the final note faded and then rose to applaud.','enrapture 是及物动词，常以 audience、listener 等作宾语。','听众沉浸于演奏并热烈鼓掌，显示强烈愉悦。'),M('The singer enraptured the audience, who were bored, left early, and refused to listen.','The singer disappointed the audience, who were bored, left early, and refused to listen.','无聊、早退表示失望而非陶醉；disappointed 符合结果。'),[Q('enrapture',1,1,'A performance that enraptures its audience?','fills them with great delight','makes them forget how to hear','forces them to leave the hall','enrapture 表示使人狂喜或着迷。'),Q('enrapture',2,1,'Which scene suggests the crowd was enraptured?','They listened motionless and applauded for several minutes.','They talked loudly through the whole show.','They left before the first act ended.','全神贯注并长时间鼓掌体现着迷与欣喜。'),Q('enrapture',3,1,'Choose the closest paraphrase: “The view enraptured her.”','The view delighted her intensely.','The view made her furious.','The view gave her an appointment.','enrapture 可改述为使人极其愉悦。'),Q('enrapture',4,1,'A child might be enraptured by?','a magical puppet show','a blank wall with nothing happening','a spoiled meal that made them ill','精彩的木偶戏可能令孩子着迷。')]);
P('enrichment','enrichment 由 enrich 加 -ment 构成，可指品质、知识、经验或营养方面的充实与增加。',C('enrichment.s1','教育','The after-school program offers enrichment through small science projects that let pupils test ideas rather than memorize definitions.','课后项目通过小型科学实验促进学生拓展学习，让他们检验想法而非死记定义。','The after-school program offers enrichment / through small science projects / that let pupils test ideas rather than memorize definitions.','enrichment 常作不可数名词，可与 cultural、educational 等搭配。','实验拓展知识经验，符合充实、丰富义。'),M('The enrichment course gave students less knowledge, fewer activities, and no new experience.','The remedial course gave students less knowledge, fewer activities, and no new experience.','没有增加知识或经验不能称 enrichment；remedial 指补习课程。'),[Q('enrichment',1,1,'An enrichment activity is designed to?','add useful depth or experience','remove all learning from a course','replace a student’s name','enrichment 指增进知识、经验或质量。'),Q('enrichment',2,1,'Soil enrichment might involve?','adding nutrients that help plants grow','removing every nutrient from the soil','painting the soil blue','增加土壤养分能改善土壤质量。'),Q('enrichment',3,1,'Which phrase is most natural?','cultural enrichment','enrichmentless culture','culture enrichmented','cultural enrichment 是自然搭配。'),Q('enrichment',4,1,'A museum visit can provide educational enrichment by?','letting students connect classroom ideas with objects','preventing students from asking questions','removing all context from the exhibits','实物参观能丰富并拓展课堂学习。')]);
P('enroll','enroll 源自古法语 enroller“列入名册”，有及物“登记某人”和不及物“本人注册”两种用法。',C('enroll.s2','课程注册','After comparing the evening schedule with her work shifts, Lila decided to enroll in the ceramics course that began in September.','莉拉对照晚间课程表和工作班次后，决定注册九月开课的陶艺课程。','After comparing the evening schedule with her work shifts / Lila decided to enroll in the ceramics course / that began in September.','不及物义通常用 enroll in + 课程；美式 enroll，英式常拼 enrol。','Lila 本人加入课程，符合 s2。'),M('Lila enrolled the course in September by joining it as a student.','Lila enrolled in the course in September by joining it as a student.','描述本人注册课程应使用 enroll in；及物 enroll 要以被登记的人作宾语。'),[Q('enroll',1,2,'A student who enrolls in a course?','officially joins it as a student','writes the course textbook','cancels every class','enroll in 表示注册加入课程。'),Q('enroll',2,1,'A school may enroll a new pupil by?','adding the pupil to its official list','removing the pupil’s desk','asking the pupil to teach the head teacher','及物 enroll 可指学校登记某学生。'),Q('enroll',3,2,'Choose the natural phrase: “He plans to ___ a nursing program.”','enroll in','enroll to','enrolling at into','enroll in a program 是常见搭配。'),Q('enroll',4,2,'Which sentence uses the intransitive sense?','The volunteers enrolled in a first-aid course.','The registrar enrolled the volunteers in a course.','The course enrolled the volunteers on its list.','主语 volunteers 自行加入课程，属于不及物义。')]);
P('enrollment','enrollment 由 enroll 加 -ment 构成，既指正式注册，也可指注册人数。',C('enrollment.s1','学校行政','Enrollment in the evening program increased after the college added childcare, allowing more working parents to attend classes.','学院增设托儿服务后，夜校的注册人数上升，使更多在职家长能够上课。','Enrollment in the evening program increased / after the college added childcare / allowing more working parents to attend classes.','enrollment 可指注册过程或人数；此句由 increased 表明是人数。','人数增加对应 enrollment 的学生注册人数义。'),M('The college reported rising enrollment even though fewer students registered than the previous year.','The college reported falling enrollment even though fewer students registered than the previous year.','注册人数减少对应 falling 而非 rising enrollment。'),[Q('enrollment',1,1,'A rise in school enrollment means?','more people have registered','more classrooms have been painted','the school has closed','enrollment 可指注册人数，人数上升即注册者变多。'),Q('enrollment',2,1,'The enrollment process usually includes?','officially signing up for a course or institution','taking a final exam before applying','graduating before joining','enrollment 指登记注册这一过程。'),Q('enrollment',3,1,'Which phrase is natural?','college enrollment','college enrollness','college enrollationed','college enrollment 是标准名词搭配。'),Q('enrollment',4,1,'A school compares this year’s enrollment with last year’s to learn?','how many students registered each year','how many books each teacher owns','which student wrote the timetable','比较 enrollment 可了解每年注册人数。')]);
P('ensconce','ensconce 的更早构词史并不完全确定；现代英语用它表示把人安置在舒适、隐蔽或安全的位置。',C('ensconce.s1','休息','By noon the cat had ensconced itself on the warm shelf above the radiator, where the household noise barely disturbed it.','中午时猫已经安然窝在暖气片上方的温暖架子上，屋里的声响几乎打扰不到它。','By noon the cat had ensconced itself / on the warm shelf above the radiator / where the household noise barely disturbed it.','常见反身结构 ensconce oneself；位置短语说明安置地点。','猫舒适地待在隐蔽温暖处，符合此义。'),M('The visitors were ensconced in a draughty corridor with no seats and nowhere sheltered from the rain.','The visitors were left waiting in a draughty corridor with no seats and nowhere sheltered from the rain.','无遮蔽、无座位且淋雨的走廊无法让访客舒适安置；改为 left waiting 消除矛盾。'),[Q('ensconce',1,1,'To ensconce oneself somewhere is to?','settle into a comfortable or sheltered place','run away from every place','make a place larger','ensconce 常表示安稳地安置或藏身。'),Q('ensconce',2,1,'Which scene fits “ensconce”?','A traveler settles by the fire in a sheltered corner.','A traveler stands exposed in a storm.','A traveler demolishes the room.','在避风角落舒适安坐符合 ensconce。'),Q('ensconce',3,1,'Choose the natural form: “She ensconced ___ in the window seat.”','herself','her','she','反身用法是 ensconce oneself。'),Q('ensconce',4,1,'An object ensconced in a padded case is?','securely nestled inside it','left loose on the road','used to cut through the case','被衬垫包护的物品处于安稳放置状态。')]);
P('enslave','enslave 由 en- 与 slave 构成，意为强迫某人沦为奴隶，也可比喻使人受某种力量支配。',C('enslave.s1','历史','The abolitionist archive records how armed traders enslaved villagers and sold them far from their homes, separating families for profit.','废奴档案记载，武装贩运者奴役村民并把他们卖到远离家乡的地方，为牟利拆散家庭。','The abolitionist archive records how armed traders enslaved villagers / and sold them far from their homes / separating families for profit.','及物动词，后接被奴役者；过去式 enslaved。','强迫村民失去自由并被买卖，符合字面义。'),M('The invaders enslaved the villagers by freeing them from forced labor and returning their choices.','The invaders liberated the villagers by freeing them from forced labor and returning their choices.','恢复自由与奴役相反，应使用 liberated。'),[Q('enslave',1,1,'To enslave a person is to?','force that person into slavery','give that person a paid holiday','teach that person to read','enslave 的字面义是奴役。'),Q('enslave',2,1,'“Debt enslaved him” is figurative and means debt?','controlled his choices so severely that he could not act freely','made him a legal owner of a bank','taught him how to lend money','比喻用法强调债务严重限制个人选择。'),Q('enslave',3,1,'Which historical action is correctly described as enslaving people?','forcing them to work without freedom or consent','hiring them with fair pay and the right to leave','inviting them to a voluntary class','强迫劳动且无自由属于奴役。'),Q('enslave',4,1,'The closest opposite of enslave is?','liberate','capture','subjugate','liberate 意为解放，与奴役相反。')]);

P('ensnare','ensnare 由 en- 与 snare“陷阱”构成，字面指捕获，也常比喻使人落入骗局或困境。',C('ensnare.s1','野生动物保护','The conservation team checked the wire loop each morning so that no fox would be ensnared while crossing the field at night.','保护团队每天早晨检查铁丝套索，避免狐狸夜间穿过田地时被套住。','The conservation team checked the wire loop each morning / so that no fox would be ensnared / while crossing the field at night.','及物动词；被动式 be ensnared 表示被陷阱捕获。','套索会捕获狐狸，对应字面义。'),M('The conservation team ensnared the fox by opening the cage and letting it run free.','The conservation team released the fox by opening the cage and letting it run free.','打开笼子让狐狸自由离开是 release，而非捕获。'),[Q('ensnare',1,1,'A trap may ensnare an animal by?','catching it so that escape is difficult','feeding it and guiding it home','teaching it to avoid roads','ensnare 指捕获或使其难以脱身。'),Q('ensnare',2,1,'A scam can ensnare a victim by?','drawing the person into a dishonest scheme','giving the person a refund immediately','publishing a warning before contact','比喻义是使人陷入骗局。'),Q('ensnare',3,1,'Which verb is closest to ensnare?','trap','release','welcome','trap 表示设法捕获，与 ensnare 接近。'),Q('ensnare',4,1,'The bird was ensnared in a net. What happened?','It became caught in the net.','It built the net.','It flew over the net untouched.','被动结构表示鸟被网困住。')]);
P('ensure','ensure 由 en- 与 sure（确定的）构成，指采取措施使结果确定；与表示投保的 insure 区分。',C('ensure.s1','安全检查','Before reopening the footbridge, engineers tested each support to ensure that it could carry the weight of a full maintenance crew.','重新开放人行桥前，工程师测试了每个支撑点，以确保桥梁能承受整支维修队的重量。','Before reopening the footbridge / engineers tested each support / to ensure that it could carry the weight of a full maintenance crew.','ensure 可接名词或 that 从句；此处 that 从句说明要确保的结果。','测试支撑点以保证桥梁承重，符合 curated source 的“确保”义。'),M('The engineer skipped every load test to ensure that the bridge was safe.','The engineer completed every load test to ensure that the bridge was safe.','跳过全部承重测试无法确保安全；改为完成测试与目的相符。'),[Q('ensure',1,1,'To ensure a door is locked, you should?','check it and take steps to make certain it is locked','assume it is open without looking','buy insurance for the hinges','ensure 表示使某事确定发生或成立。'),Q('ensure',2,1,'Which phrase uses ensure correctly?','ensure that every file is backed up','ensure against a house for fire','ensure a policy from the insurer','ensure that + 从句表示确保某结果。'),Q('ensure',3,1,'A teacher checks attendance to ensure?','that every student is accounted for','that the class has no lesson','that the register is hidden','检查出勤是为确认学生均已登记。'),Q('ensure',4,1,'Choose the best contrast: “ensure safety” means ___; “insure a car” means ___.','make safety certain; buy financial protection for a car','buy safety as an object; make the car certain','repair safety; make the car faster','ensure 是确保；insure 常指投保。')]);
P('entanglement','entanglement 由 entangle 加 -ment 构成，可指线物缠绕，也指复杂纠葛或卷入关系。',C('entanglement.s1','法律调查','The investigator found an entanglement of business and family interests that made it difficult to tell who had approved the contract.','调查人员发现商业利益与家庭利益交织纠缠，难以判断究竟是谁批准了合同。','The investigator found an entanglement of business and family interests / that made it difficult to tell / who had approved the contract.','entanglement 常与 in/of 搭配；此处指复杂的利益纠葛。','利益关系混在一起、难以厘清，体现 entanglement 的纠葛义。'),M('The auditor praised the clean separation of interests as a serious entanglement.','The auditor praised the clean separation of interests as a safeguard against entanglement.','利益清晰分开可避免纠葛，不是纠葛本身。'),[Q('entanglement',1,1,'A political entanglement is likely to involve?','a complicated involvement that is hard to separate','a simple schedule for a meeting','a transparent vote with no connections','比喻义 entanglement 指复杂卷入或纠葛。'),Q('entanglement',2,1,'Fishing line in a knot is a physical?','entanglement','enlightenment','enrollment','线打结缠绕是字面 entanglement。'),Q('entanglement',3,1,'Why can a business entanglement be risky?','overlapping interests can make responsibility unclear','every decision is independent and documented','all parties have no connection at all','利益交错会模糊责任边界。'),Q('entanglement',4,1,'Choose the natural phrase.','an entanglement of political interests','an entanglement of clear permissions','an entanglement that separated everything neatly','常与 interests、relationships 等复杂纠葛搭配。')]);
P('enterprising','enterprising 由 enterprise 加 -ing 构成，形容主动、有创造力且愿意承担新事业风险。',C('enterprising.s1','创业','An enterprising baker noticed that commuters had little time for breakfast, so she opened a small counter beside the early bus stop.','一位有创业精神的面包师注意到通勤者没有时间吃早餐，于是在早班车站旁开了个小柜台。','An enterprising baker noticed that commuters had little time for breakfast / so she opened a small counter / beside the early bus stop.','形容人或行动；强调主动发现机会并付诸行动。','她识别需求并创办新服务，体现进取主动。'),M('The enterprising owner refused to try any new idea and waited for customers to create the business for him.','The passive owner refused to try any new idea and waited for customers to create the business for him.','拒绝行动且等待他人体现被动，不符合 enterprising。'),[Q('enterprising',1,1,'An enterprising person is likely to?','take initiative and look for opportunities','avoid every new task','wait for others to make all decisions','enterprising 指积极主动、善于开创新机会。'),Q('enterprising',2,1,'Which plan sounds enterprising?','testing a new delivery service after spotting customer demand','closing the shop without asking customers why','copying a failed plan without change','发现需求后测试新服务体现主动创业精神。'),Q('enterprising',3,1,'Choose the closest meaning of an enterprising student.','resourceful and willing to act','timid and unwilling to try','already retired from study','enterprising 学生有进取心并愿意采取行动。'),Q('enterprising',4,1,'The adjective enterprising most naturally describes?','a founder who develops an original solution','a chair that has no moving parts','a deadline that passed yesterday','该词主要形容主动开拓的人或做法。')]);
P('entertainer','entertainer 来自 entertain 加施事后缀 -er，指通过表演使观众愉快的人。',C('entertainer.s1','舞台演出','The entertainer shifted from comic stories to a short juggling routine, keeping the children involved while the delayed train was announced.','这位艺人从喜剧故事转到短暂的杂耍表演；火车晚点广播时，他让孩子们始终兴致盎然。','The entertainer shifted from comic stories to a short juggling routine / keeping the children involved / while the delayed train was announced.','可数名词，可指歌手、喜剧演员或其他表演者。','讲故事并表演杂耍以取悦观众，符合词义。'),M('The entertainer refused to perform, tell stories, sing, or do anything to amuse the audience.','The ticket inspector refused to perform, tell stories, sing, or do anything to amuse the audience.','拒绝表演和娱乐观众的人在此情境下不是 entertainer。'),[Q('entertainer',1,1,'An entertainer is a person who?','performs to amuse an audience','repairs train engines','records court decisions','entertainer 指给观众带来娱乐的表演者。'),Q('entertainer',2,1,'Which person is an entertainer?','a singer performing at a festival','a plumber fixing a pipe','a clerk filing tax forms','节庆演出的歌手以表演娱乐观众。'),Q('entertainer',3,1,'A children’s entertainer might use?','jokes, songs, or magic tricks','medical scans and prescriptions','maps for surveying a road','笑话、歌曲或魔术是常见娱乐表演。'),Q('entertainer',4,1,'The suffix -er in entertainer points to?','a person who performs an activity','the place where a show is held','the past time of a performance','-er 表示执行 entertain 的人。')]);
P('entertaining','entertaining 是 entertain 的 -ing 形容词，指能带来乐趣、使人觉得有意思。',C('entertaining.s1','旅行','The guide made the long coach ride entertaining by telling local legends and inviting passengers to guess which details were historically documented.','导游讲述当地传说，并让乘客猜测哪些细节有史料依据，使漫长的长途汽车旅程变得有趣。','The guide made the long coach ride entertaining / by telling local legends / and inviting passengers to guess which details were historically documented.','make + 宾语 + entertaining；-ing 形容词描述事物产生的效果。','故事与互动让旅程有趣，符合 entertaining。'),M('The entertaining film held no one’s interest, and every viewer found it dull.','The tedious film held no one’s interest, and every viewer found it dull.','观众都觉得乏味说明电影 tedious，而非 entertaining。'),[Q('entertaining',1,1,'An entertaining book is one that?','gives readers pleasure or amusement','contains no readable words','is only useful as a doorstop','entertaining 表示有趣、能带来娱乐。'),Q('entertaining',2,1,'Which event would most likely be entertaining?','a lively show with jokes and music','a silent room with no activity','a list of numbers read without pause','笑话和音乐表演通常令人愉快。'),Q('entertaining',3,1,'Choose the natural sentence.','The host gave an entertaining speech.','The host entertainingly was a speech.','The speech entertainedly the host.','entertaining 可作形容词修饰 speech。'),Q('entertaining',4,1,'If a lecture is entertaining, listeners are likely to?','enjoy following it','find it impossible to hear','assume it has been canceled','entertaining 描述带来乐趣的讲座。')]);
P('entertainment','entertainment 可指娱乐活动或表演，也可指待客款待；由 entertain 加 -ment 构成。',C('entertainment.s3','待客','The hosts provided simple entertainment for their overnight guests, offering hot soup, clean blankets, and a quiet room after the storm.','暴风雨过后，主人为留宿客人作了简单款待，提供热汤、干净毯子和安静房间。','The hosts provided simple entertainment for their overnight guests / offering hot soup, clean blankets, and a quiet room / after the storm.','旧式或正式语境的 s3 指招待客人；不只限于演出。','热情照料留宿客人体现款待义。'),M('The hosts offered entertainment to their overnight guests by refusing food, shelter, and conversation.','The hosts offered no entertainment or hospitality to their overnight guests by refusing food, shelter, and conversation.','拒绝基本照料并非款待；改成否定表达符合实际行为。'),[Q('entertainment',1,3,'In the sense of hospitality, entertainment means?','the way guests are received and looked after','a machine for measuring room temperature','a list of guests’ debts','此义指待客、款待。'),Q('entertainment',2,1,'Which activity is entertainment?','watching a comedy performance','paying a water bill','locking an unused storeroom','看喜剧表演属于娱乐活动。'),Q('entertainment',3,2,'Theater entertainment usually refers to?','a show performed for an audience','a private insurance contract','a map of backstage exits','表演义指给观众看的节目。'),Q('entertainment',4,3,'A host provides entertainment for visitors by?','welcoming them and making their stay pleasant','asking them to leave before they arrive','hiding all available chairs','待客义包含欢迎并让客人舒适。')]);
P('enthral','enthral 是英式拼法，和 enthrall 同词，来自 en- 与 thrall“奴役、束缚”，引申为完全吸引注意力。',C('enthral.s1','演讲','The astronomer’s account of a newly observed comet enthralled the school assembly, and students stayed afterward to ask about its orbit.','天文学家讲述新发现的彗星，令全校集会上的学生听得入迷；结束后他们还留下来询问彗星轨道。','The astronomer’s account of a newly observed comet enthralled the school assembly / and students stayed afterward / to ask about its orbit.','enthral 是及物动词；英式拼写双写 l 前常省略第二个 l。','学生持续专注且主动追问，说明演讲吸引力很强。'),M('The story enthralled the audience, who paid no attention and left before it began.','The story failed to enthrall the audience, who paid no attention and left before it began.','观众不关注且提前离开，表示故事未能吸引他们；需加 failed to。'),[Q('enthral',1,1,'A story that enthrals its readers?','holds their attention completely','makes them unable to read','lists only the author’s expenses','enthral 表示使人着迷、全神贯注。'),Q('enthral',2,1,'Which spelling is the usual British variant?','enthral','enthrale','inthrall','英式拼法常写 enthral，美式常写 enthrall。'),Q('enthral',3,1,'A speaker enthralled the crowd. The crowd probably?','listened with intense interest','ignored the speech from start to finish','was forced to write the speech','全神贯注地听说明被演讲吸引。'),Q('enthral',4,1,'Choose the closest meaning of enthral.','fascinate','distract','frighten','fascinate 与 enthral 都可表示使着迷。')]);
P('enthrall','enthrall 由 en- 与 thrall“奴役、束缚”组成，现代义为牢牢吸引某人。',C('enthrall.s1','表演','The dancer’s precise footwork enthralled the judges, who watched each movement closely before awarding the performance the highest score.','舞者精准的步法深深吸引了评委；他们仔细观看每个动作后给出演出最高分。','The dancer’s precise footwork enthralled the judges / who watched each movement closely / before awarding the performance the highest score.','及物动词；过去式 enthralled，注意双写 l。','评委专注观看并给高分，表现出被表演吸引。'),M('The dancers enthralled the judges, who were bored, fell asleep, and missed the entire performance.','The dancers failed to enthrall the judges, who were bored, fell asleep, and missed the entire performance.','评委感到无聊且错过演出，说明舞者未能吸引他们。'),[Q('enthrall',1,1,'To enthrall an audience is to?','fascinate them and hold their attention','make them lose their tickets','ask them to perform instead','enthrall 表示使人着迷、注意力被牢牢吸引。'),Q('enthrall',2,1,'Which audience reaction suggests it was enthralled?','everyone followed the final scene in silence','most people left before the opening','the room remained empty','全场安静关注结尾表明观众被深深吸引。'),Q('enthrall',3,1,'Choose the correct past form.','enthralled','enthraled','enthrallted','enthrall 过去式双写 l 后加 -ed。'),Q('enthrall',4,1,'A gripping story can enthrall a reader by?','making the reader eager to continue','forcing the reader to close the book immediately','changing the reader’s handwriting','引人入胜的故事使读者想继续读下去。')]);
P('enthusiastically','enthusiastically 由 enthusiastic 加副词后缀 -ally 构成，表示热切、积极地参与或赞同。',C('enthusiastically.s1','志愿活动','When the library announced a weekend repair workshop, residents enthusiastically signed up and offered tools they could lend.','图书馆宣布周末维修工作坊后，居民们热情报名，还主动提供可借出的工具。','When the library announced a weekend repair workshop / residents enthusiastically signed up / and offered tools they could lend.','副词修饰 signed up，说明参与时的态度。','积极报名并提供工具显示热情与赞同。'),M('The volunteers enthusiastically joined the project, complaining that they wanted nothing to do with it.','The volunteers reluctantly joined the project, complaining that they wanted nothing to do with it.','抱怨不愿参与说明态度勉强，而非 enthusiastically。'),[Q('enthusiastically',1,1,'To respond enthusiastically is to respond?','with eager interest and energy','without noticing what was said','with deliberate hostility','enthusiastically 表示热情积极地。'),Q('enthusiastically',2,1,'Which response is enthusiastic?','“I’d love to help; I can bring the tools.”','“I refuse to hear another word.”','“I have no idea what you asked.”','主动答应并带工具表现积极热情。'),Q('enthusiastically',3,1,'Choose the best fit: “The fans ___ cheered when the team scored.”','enthusiastically','erroneously','equatorially','热情地欢呼应使用 enthusiastically。'),Q('enthusiastically',4,1,'A student participates enthusiastically when the student?','asks eager questions and joins the activity','sits out and complains throughout','leaves before the instructions begin','主动提问并参加活动表现热忱。')]);
P('entitative','entitative 是较少用的哲学形容词，与 entity（实体）和拉丁语 ens“存在者”相关，指作为独立实体存在的。',C('entitative.s1','哲学','The philosopher used entitative language for the river, treating it as a distinct being rather than merely a label for connected streams.','这位哲学家用实体性的语言谈论那条河，把它视为一个独立存在者，而不只是相连溪流的名称。','The philosopher used entitative language for the river / treating it as a distinct being / rather than merely a label for connected streams.','罕见学术形容词，通常修饰 status、claim 或 language。','把河视为独立存在者，对应“作为实体的”。'),M('The article made an entitative claim that the river had no distinct existence and was only a name for unrelated drops.','The article made a non-entitative claim that the river had no distinct existence and was only a name for unrelated drops.','否认独立存在并不符合 entitative；加 non- 改变其判断。'),[Q('entitative',1,1,'An entitative account treats something as?','a distinct entity','a grammatical tense','a measured temperature','entitative 与实体存在有关。'),Q('entitative',2,1,'A philosopher asks whether a group has entitative status. The issue is whether it?','exists as a distinct thing','has a particular spelling','is located near the equator','entitative status 讨论是否作为独立实体存在。'),Q('entitative',3,1,'Which topic most plausibly uses entitative?','whether a corporation is a separate legal entity','how to bake bread evenly','how to tune a violin','该词属于实体与存在的学术讨论。'),Q('entitative',4,1,'The closest simple paraphrase of entitative is?','having the nature of an entity','moving in a straight line','being full of enthusiasm','entity 表示实体，entitative 描述实体性的。')]);
P('entomb','entomb 由 en- 与 tomb“墓”构成，意为埋入墓中，也可指被废墟、冰雪等掩埋困住。',C('entomb.s1','灾害救援','The collapse entombed two workers beneath concrete slabs, and rescuers listened for tapping before deciding where to cut.','坍塌使两名工人被埋困在混凝土板下，救援人员先听敲击声，再决定从哪里切开。','The collapse entombed two workers beneath concrete slabs / and rescuers listened for tapping / before deciding where to cut.','及物动词，常见被动 be entombed beneath/in；不一定指正式墓葬。','工人被废墟掩埋，体现引申的埋困义。'),M('The collapse entombed the workers by lifting every slab away and leaving them in open daylight.','The collapse freed the workers by lifting every slab away and leaving them in open daylight.','清除板材、重见天日是 freed，不是被埋困。'),[Q('entomb',1,1,'A person entombed by rubble is?','trapped beneath the collapsed material','standing safely above it','painting the rubble','entomb 可指被废墟掩埋困住。'),Q('entomb',2,1,'In its literal burial sense, to entomb a body is to?','place it in a tomb','remove it from a tomb','write its name on a map','字面义是将遗体安葬于墓中。'),Q('entomb',3,1,'Which event could entomb a vehicle?','a landslide covering it under earth and rock','a mechanic washing it','a driver parking it in a garage','滑坡覆盖车辆会将其掩埋。'),Q('entomb',4,1,'The verb entomb is formed around which idea?','placing or enclosing within a tomb-like covering','making something more enthusiastic','asking a question formally','词形由 en- 和 tomb 组成，核心是埋入或包围。')]);
P('entourage','entourage 借自法语 entourage，源自 entourer“环绕”，指陪同名人或权势者的随行人员。',C('entourage.s1','外交访问','The minister arrived with a small entourage of aides and translators, but she asked them to wait outside during the private meeting.','部长带着由助理和译员组成的小型随行团队抵达，但她请他们在闭门会议期间等在外面。','The minister arrived with a small entourage of aides and translators / but she asked them to wait outside / during the private meeting.','可数集合名词，常用 an entourage of + 人员。','助理和译员陪同部长出行，属于其随行人员。'),M('The minister’s entourage consisted of an empty conference room and no people traveling with her.','The minister’s entourage consisted of aides and translators traveling with her.','entourage 指随行人员，不可能由空会议室组成。'),[Q('entourage',1,1,'A celebrity’s entourage is?','the group of people accompanying the celebrity','the celebrity’s travel suitcase','a list of fans at home','entourage 是陪同某人的团队。'),Q('entourage',2,1,'Which person would likely belong to a diplomat’s entourage?','an aide traveling with the diplomat','a stranger reading the news abroad','a local who has never met the diplomat','同行助理属于随行人员。'),Q('entourage',3,1,'Choose the natural phrase.','an entourage of advisers','an entourage of empty rooms','an entourage for walking alone','常说 entourage of + 随行人群。'),Q('entourage',4,1,'The word entourage originally suggests people who?','surround or accompany someone','repair a tomb','study the equator','法语词源与“环绕”相关，现代指随行团队。')]);
P('entrap','entrap 由 en- 与 trap 构成，可指捕获困住，也可指诱使某人落入圈套。',C('entrap.s2','执法程序','The judge dismissed the charge because the officers had repeatedly pressured the suspect to commit an offense he had not planned.','法官撤销了指控，因为警员一再施压，诱使嫌疑人犯下原本没有计划的罪行。','The judge dismissed the charge / because the officers had repeatedly pressured the suspect / to commit an offense he had not planned.','法律语境 s2 常指诱使他人犯罪的 entrapment；动词可用被动 be entrapped。','警方施压诱导实施原本未计划的罪行，符合诱骗义。'),M('The officers entrapped the suspect by refusing to tempt, pressure, or persuade him to commit any offense.','The officers did not entrap the suspect because they refused to tempt, pressure, or persuade him to commit any offense.','明确没有诱导或施压就不构成 entrap；加入否定纠正判断。'),[Q('entrap',1,2,'To entrap someone in a legal context may mean to?','induce the person to commit an offense','help the person appeal a verdict','record the person’s fingerprints','法律义指诱使当事人犯罪。'),Q('entrap',2,1,'A wild animal can be entrapped when it is?','caught so that it cannot easily escape','fed and released','observed from a distant hill','字面义是使动物落入陷阱难以逃脱。'),Q('entrap',3,2,'Which action risks entrapment?','repeatedly urging someone to commit a crime they had not intended','warning someone not to break the law','investigating a crime after it occurs','反复诱导他人犯罪可能构成 entrapment。'),Q('entrap',4,1,'The prefix en- in entrap helps form a verb meaning?','to put or catch someone in a trap','to remove a trap safely','to study a trap’s history','entrap 可理解为使人落入 trap。')]);
P('entreat','entreat 源于古法语 entraiter，和 traiter“处理、交涉”相关，现代意为郑重恳求。',C('entreat.s1','家庭','She entreated her brother to wait until the doctor arrived, explaining that the road was too icy for him to drive alone.','她恳求哥哥等医生到了再走，并解释说路面太滑，他不该独自开车。','She entreated her brother to wait until the doctor arrived / explaining that the road was too icy / for him to drive alone.','及物动词，常用 entreat someone to do；语气比普通 ask 强烈。','她郑重请求哥哥等待，符合恳求义。'),M('She entreated him to ignore her plea and leave immediately.','She urged him to ignore her plea and leave immediately.','entreat someone to do 通常表示恳求对方去做所述动作；ignore plea 和恳求矛盾。'),[Q('entreat',1,1,'To entreat someone is to?','beg that person seriously','give that person a receipt','punish that person immediately','entreat 表示郑重恳求。'),Q('entreat',2,1,'Choose the natural pattern.','entreat a friend to stay','entreat a friend staying','entreat to a friend stay','常用 entreat someone to do。'),Q('entreat',3,1,'Which speaker is entreating?','“Please, I beg you to give the witness time.”','“The room is painted blue.”','“Your train leaves at noon.”','郑重请求对方给证人时间，属于恳求。'),Q('entreat',4,1,'Entreat is closest in meaning to?','implore','ignore','entomb','implore 与 entreat 都表示恳求。')]);
P('entrenched','entrenched 源自 entrench“筑壕固守”，由战壕防御引申为牢固确立、难以改变。',C('entrenched.s1','组织改革','The outdated promotion system was so entrenched that even managers who opposed it struggled to change how vacancies were filled.','过时的晋升制度根深蒂固，以至于反对它的经理也难以改变职位空缺的填补方式。','The outdated promotion system was so entrenched / that even managers who opposed it / struggled to change how vacancies were filled.','常与 belief、system、attitude、privilege 搭配；表示改变困难。','制度长期牢固存在，符合 entrenched 的引申义。'),M('The entrenched custom vanished overnight without opposition and had never shaped anyone’s behavior.','The fragile custom vanished overnight without opposition and had never shaped anyone’s behavior.','一夜消失且影响甚微的习俗并不根深蒂固。'),[Q('entrenched',1,1,'An entrenched belief is?','firmly established and difficult to change','newly invented yesterday','forgotten by everyone','entrenched 表示根深蒂固、难以改变。'),Q('entrenched',2,1,'Which institution has an entrenched practice?','one that has persisted for decades despite reform attempts','one that was introduced this morning','one that no member has ever followed','多年持续且难以改革符合 entrenched。'),Q('entrenched',3,1,'Choose the closest opposite of entrenched.','temporary','deep-rooted','firmly established','temporary 表示暂时的，与根深蒂固相反。'),Q('entrenched',4,1,'An entrenched privilege is difficult to?','remove because it is firmly established','notice because it has never existed','translate into another language','entrenched 描述已牢固建立的特权。')]);
P('entrepreneurial','entrepreneurial 来自 entrepreneur 加形容词后缀 -ial；entrepreneur 借自法语 entreprendre“着手承担”。',C('entrepreneurial.s1','商业','Her entrepreneurial approach paired a small repair service with online booking, letting residents request affordable fixes instead of replacing appliances.','她以创业思维把小型维修服务与线上预约结合，让居民可以申请低价维修而不必更换家电。','Her entrepreneurial approach paired a small repair service with online booking / letting residents request affordable fixes / instead of replacing appliances.','形容词修饰 approach、skill、spirit 等，强调创办业务和承担风险。','她创造新服务模式并实施，体现创业精神。'),M('His entrepreneurial approach avoided every business idea, risk, customer, and attempt to start a venture.','His risk-averse approach avoided every business idea, risk, customer, and attempt to start a venture.','避开一切创业行动说明厌恶风险，不是 entrepreneurial。'),[Q('entrepreneurial',1,1,'An entrepreneurial idea is connected with?','starting or developing a business venture','memorizing a poem without interpretation','repairing a clock only as a hobby','entrepreneurial 与创办或发展企业有关。'),Q('entrepreneurial',2,1,'Which quality is entrepreneurial?','spotting a need and organizing a new service','rejecting all initiative and waiting indefinitely','copying figures without making decisions','发现需求并组织新服务体现创业能力。'),Q('entrepreneurial',3,1,'Choose the natural phrase.','entrepreneurial skills','entrepreneurialnessly','entrepreneuring skills','entrepreneurial skills 是自然搭配。'),Q('entrepreneurial',4,1,'An entrepreneurial culture often encourages?','initiative and calculated risk-taking','avoiding every change','hiding all new proposals','创业文化鼓励主动性和审慎承担风险。')]);
P('entrepreneurship','entrepreneurship 由 entrepreneur 加 -ship 构成，指创办、经营企业及其所需的主动性和承担风险。',C('entrepreneurship.s1','职业教育','The college added entrepreneurship to its evening curriculum, where students learn to test a market before borrowing money to open a shop.','学院把创业课程加入夜校，学生将在借钱开店前学习如何测试市场需求。','The college added entrepreneurship to its evening curriculum / where students learn to test a market / before borrowing money to open a shop.','不可数名词，常用于 business、education、social entrepreneurship 等语境。','课程讲授开办企业的过程和判断，符合 entrepreneurship。'),M('Entrepreneurship is the study of avoiding all business activity and never organizing a venture.','Business inactivity is the avoidance of all business activity and organizing a venture.','创业指发起与经营企业；完全避免企业活动与之相反。'),[Q('entrepreneurship',1,1,'Entrepreneurship concerns?','starting and running ventures','the study of ancient handwriting only','the construction of moving staircases','entrepreneurship 指创业及经营新事业。'),Q('entrepreneurship',2,1,'A course in entrepreneurship might teach students to?','identify customers and plan a viable new business','avoid talking to customers','spend money without a plan','创业课程训练市场识别和业务规划。'),Q('entrepreneurship',3,1,'Which phrase is standard?','social entrepreneurship','social entrepreneurshiping','socially entrepreneurshiped','social entrepreneurship 是标准表达。'),Q('entrepreneurship',4,1,'The suffix -ship in entrepreneurship helps form a noun for?','a field, activity, or condition','a past action only','the location of a shop','-ship 可构成表示身份、领域或活动状态的名词。')]);
P('entwine','entwine 由 en- 与 twine“缠绕的线”构成，可指实物缠绕，也可比喻生活或思想交织。',C('entwine.s2','人物关系','The memoir shows how the sisters’ lives became entwined through shared work, migration, and years of caring for the same relatives.','这部回忆录展现两姐妹的人生如何因共同工作、迁徙以及多年照料同一批亲人而紧密交织。','The memoir shows how the sisters’ lives became entwined / through shared work, migration, and years of caring / for the same relatives.','s2 为比喻义，常见 lives/interests become entwined。','共同经历让两人的生活难以分开，符合引申义。'),M('Their lives became entwined because they never met, shared no experiences, and lived entirely separate histories.','Their lives remained separate because they never met, shared no experiences, and lived entirely separate histories.','从未相识且经历完全分开，不能说生活交织。'),[Q('entwine',1,2,'When two people’s lives become entwined, they?','become closely connected','move to opposite sides of the globe with no contact','stop existing','比喻义表示生活或关系紧密相连。'),Q('entwine',2,1,'Vines entwine a fence when they?','wind and grow around it','cut it into small pieces','measure its height','植物绕着栅栏生长是字面缠绕。'),Q('entwine',3,2,'Which sentence uses the figurative sense?','Their careers became entwined through a shared research project.','The rope entwined around the post.','The vine entwined the garden gate.','共同项目使职业道路交织，属于比喻义。'),Q('entwine',4,1,'The closest meaning of entwine is?','interweave','separate','enlarge','interweave 表示交织缠绕。')]);
P('enunciate','enunciate 源自拉丁语 enuntiare“宣布、表达”，可指清晰发音，也可指正式阐明观点。',C('enunciate.s2','政策说明','The chair enunciated the new policy in plain terms, specifying which records could be shared and which required written consent.','主席用清楚的措辞阐明新政策，明确哪些记录可以共享、哪些需要书面同意。','The chair enunciated the new policy in plain terms / specifying which records could be shared / and which required written consent.','s2 指清楚阐述；enunciate an idea/policy/principle。','明确阐述政策细节，符合 s2。'),M('The chair enunciated the policy by refusing to state it, leaving members with no idea what it required.','The chair failed to enunciate the policy clearly, leaving members with no idea what it required.','没有表达政策内容就不是清楚阐述；应否定 enunciate clearly。'),[Q('enunciate',1,1,'To enunciate a word clearly is to?','pronounce its sounds distinctly','swallow every syllable','change its spelling','enunciate 的常见义之一是清晰发音。'),Q('enunciate',2,2,'A chair enunciates a policy when the chair?','states it clearly and formally','hides it from the members','forgets what it says','另一义是清楚、正式地阐明。'),Q('enunciate',3,1,'A speech coach may ask a speaker to enunciate by?','making each consonant easier to hear','speaking with a mouth full of food','mumbling into a pillow','清楚发出辅音有助于听懂。'),Q('enunciate',4,2,'Which object can be enunciated in the sense of “state clearly”?','a principle','a staircase step','a lunch plate','原则可以被清楚阐明。')]);
P('enure','enure 是较少见的变体，和 inure 同源；inure 源自法语用法，现代常见形式表示使人逐渐习惯艰苦条件。',C('enure.s1','艰苦训练','Repeated field exercises enured the recruits to cold rain, though the instructors still required proper clothing and medical checks.','反复的野外训练使新兵逐渐习惯冷雨天气，不过教官仍要求他们穿戴得当并接受健康检查。','Repeated field exercises enured the recruits to cold rain / though the instructors still required proper clothing / and medical checks.','enure 可作及物动词；现代英语更常用 inure，常见 enure someone to something。','训练使新兵逐步适应艰苦环境，符合此义。'),M('The mild climate enured the hikers to freezing nights even though they had never experienced cold weather.','The mild climate did not enure the hikers to freezing nights because they had never experienced cold weather.','从未经历冷天且气候温和，不足以使人习惯冰冻夜晚。'),[Q('enure',1,1,'To enure someone to hardship is to?','make that person accustomed to it','make the hardship disappear','give that person a new title','enure 指使人逐渐习惯艰苦。'),Q('enure',2,1,'Which is the more familiar modern variant of enure?','inure','ensure','endurement','enure 与 inure 是变体关系；ensure 义不同。'),Q('enure',3,1,'Choose the natural construction.','enure a crew to long nights','enure a crew at long nights','enure to a crew long nights','该义通常是 enure someone to something。'),Q('enure',4,1,'Gradual exposure enured the trainees to the noise. They?','became accustomed to it','became unable to hear anything','caused the noise to stop','enure 在这里是使逐渐适应。')]);
P('environmental','environmental 由 environment 加形容词后缀 -al 构成，指自然环境或周围条件相关的。',C('environmental.s1','城市规划','The council required an environmental review before approving the road, because the proposed route crossed a wetland used by migrating birds.','由于拟建道路穿过候鸟栖息的湿地，市议会要求在批准前进行环境评估。','The council required an environmental review before approving the road / because the proposed route crossed a wetland / used by migrating birds.','environmental 修饰 review、impact、policy 等名词。','评估道路对湿地的影响，属于环境相关审查。'),M('The environmental report studied only the color of office furniture and ignored the wetland, wildlife, and emissions.','The interior-design report studied only the color of office furniture and ignored the wetland, wildlife, and emissions.','只研究室内家具颜色与环境议题无关。'),[Q('environmental',1,1,'An environmental policy is concerned with?','the natural world and effects on it','the spelling rules of a language','the price of a concert ticket','environmental 指与环境有关。'),Q('environmental',2,1,'Which item is an environmental concern?','chemical runoff entering a river','a singer changing costumes','a printer using blue ink on one page','污染物流入河流会影响环境。'),Q('environmental',3,1,'Choose the natural collocation.','environmental protection','environmental protectful','environmental protectment','environmental protection 是常见搭配。'),Q('environmental',4,1,'An environmental impact assessment would examine?','how a project may affect land, water, or wildlife','how a poem scans','how many seats are in a theater','该评估关注项目对自然环境的影响。')]);
P('environmentalist','environmentalist 由 environment 加 -alist 构成，指为保护自然环境而工作或倡议的人。',C('environmentalist.s1','公众倡议','The environmentalist presented water samples to the council and asked for stricter controls on the factory’s discharge into the marsh.','这位环保人士向议会出示水样，并要求严格控制工厂向沼泽排放污水。','The environmentalist presented water samples to the council / and asked for stricter controls / on the factory’s discharge into the marsh.','可数名词，常指从事保护自然、倡议政策或相关研究的人。','她倡议控制污染、保护湿地，符合 environmentalist。'),M('The environmentalist campaigned to increase toxic dumping and oppose every effort to protect the marsh.','The polluter campaigned to increase toxic dumping and oppose every effort to protect the marsh.','支持增加有毒排放与环保倡议相反，不能称为环保人士。'),[Q('environmentalist',1,1,'An environmentalist is someone who works to?','protect the natural environment','design household furniture','measure the length of a poem','environmentalist 指保护自然环境的人。'),Q('environmentalist',2,1,'Which activity fits an environmentalist?','organizing a campaign to protect a local wetland','promoting the dumping of waste into a river','selling tickets for a theater','倡议保护湿地属于环境保护行动。'),Q('environmentalist',3,1,'An environmentalist might study?','the effects of pollution on wildlife','the stitching of a stage costume','the grammar of a fictional language only','研究污染对野生生物的影响与环保有关。'),Q('environmentalist',4,1,'The suffix -ist in environmentalist points to?','a person associated with an activity or cause','a place where waste is stored','the past form of a verb','-ist 常表示从事某领域或支持某事业的人。')]);
P('environmentally','environmentally 是 environmental 加副词后缀 -ly，表示从环境角度而言或对环境的影响方面。',C('environmentally.s1','产品选择','The company switched to environmentally safer packaging that uses less plastic and can be recycled through the town’s existing collection system.','公司改用了对环境更安全的包装，塑料用量更少，而且可通过镇上现有回收系统处理。','The company switched to environmentally safer packaging / that uses less plastic / and can be recycled through the town’s existing collection system.','常修饰 friendly、safe、damaging、sustainable 等形容词。','少用塑料并可回收，体现环境影响更小。'),M('The factory is environmentally friendly because it releases untreated chemicals into the river each night.','The factory is environmentally harmful because it releases untreated chemicals into the river each night.','夜间排放未经处理的化学物质会造成污染，不是环保。'),[Q('environmentally',1,1,'An environmentally safe product is designed to?','reduce harm to the natural environment','increase pollution without warning','make no reference to its packaging','environmentally 修饰 safe，表示对环境安全。'),Q('environmentally',2,1,'Choose the correct phrase.','environmentally friendly transport','environmentally friend transport','environmentalily friendly transport','常用 environmentally friendly。'),Q('environmentally',3,1,'A process is environmentally damaging if it?','pollutes nearby soil and water','uses less energy and avoids waste','protects a nesting area','污染土壤与水体对环境有害。'),Q('environmentally',4,1,'The ad says a cleaner is environmentally preferable. This means?','its environmental effects are considered better','it is cheaper in every store','it has no cleaning function','该副词表示比较其环境影响。')]);
P('envision','envision 由 en- 与 vision 构成，意为在心中形成图景，尤其是设想未来可能发生的情况。',C('envision.s1','城市规划','The architects envision a public square where market stalls, shade trees, and an accessible path can coexist without blocking the bus stop.','建筑师设想建成一处公共广场，让集市摊位、遮荫树木和无障碍通道共存而不挡住公交站。','The architects envision a public square / where market stalls, shade trees, and an accessible path can coexist / without blocking the bus stop.','及物动词，可接名词或宾语从句；常谈计划或未来方案。','建筑师描述尚未建成的广场构想，体现“设想”。'),M('The planners envisioned a future district by refusing to imagine any possible streets, services, or public spaces.','The planners failed to envision a future district because they refused to imagine any possible streets, services, or public spaces.','拒绝设想任何未来要素，就没有 envision 一个地区。'),[Q('envision',1,1,'To envision a future project is to?','imagine what it could be like','measure what it was last year','cancel it without discussion','envision 指在心中设想未来可能性。'),Q('envision',2,1,'Which sentence uses envision naturally?','We envision a safer route for children walking to school.','We envision the receipt at exactly three dollars.','We envision the keys by handing them to the clerk.','设想更安全的未来路线是自然用法。'),Q('envision',3,1,'A designer envisions a new chair before building it by?','forming a mental picture of the design','forgetting that chairs exist','recording the chair’s weight after delivery','envision 可指在制作前想象设计。'),Q('envision',4,1,'“She envisioned that the project would serve nearby villages” means she?','imagined that future outcome','proved it had already happened','refused to consider it','设想项目将服务村庄，描述预期未来。')]);
P('enzyme','enzyme 由希腊语 en zymē“在酵母中”构成，词名由生化学家 Wilhelm Kühne 于 19 世纪提出，指催化生物化学反应的物质。',C('enzyme.s1','生物学','The enzyme in the sample sped up the breakdown of starch, while the control tube without it changed much more slowly.','样品中的酶加快了淀粉分解，而不含酶的对照试管变化慢得多。','The enzyme in the sample sped up the breakdown of starch / while the control tube without it / changed much more slowly.','enzyme 作可数名词；它催化反应而通常不被反应消耗。','对照显示该物质加速了生化过程，符合酶的作用。'),M('The enzyme slowed the reaction by being used up as the reaction’s final product.','The inhibitor slowed the reaction by interfering with the enzyme.','催化剂加快反应且不作为终产物被耗尽；减速可由 inhibitor 解释。'),[Q('enzyme',1,1,'An enzyme in a cell generally?','speeds up a chemical reaction','stores a genetic family tree','forms the outer layer of skin','酶通常催化并加快细胞中的化学反应。'),Q('enzyme',2,1,'Why compare a sample with a tube lacking the enzyme?','to see whether the enzyme changes the reaction rate','to measure the color of the lab coat','to count the researchers in the room','无酶对照用于比较其对反应速度的影响。'),Q('enzyme',3,1,'Digestive enzymes help the body?','break food molecules into smaller substances','turn every nutrient into bone','stop all chemical reactions','消化酶协助分解食物分子。'),Q('enzyme',4,1,'Which statement about an enzyme is accurate?','It catalyzes a reaction without being the ordinary final product.','It is always a whole animal.','It can only act outside living cells.','酶起催化作用，通常不作为反应终产物。')]);
P('eohippus','Eohippus 由希腊语 ēōs“黎明”与 hippos“马”构成，意为“黎明之马”，是早期已灭绝马类的旧称。',C('eohippus.s1','古生物学','The museum label identifies Eohippus as a small early equid, while noting that later research revised parts of the traditional horse-evolution story.','博物馆标签将始祖马标为体型较小的早期马科动物，同时说明后来的研究修订了传统马类演化叙述的部分内容。','The museum label identifies Eohippus as a small early equid / while noting that later research revised parts / of the traditional horse-evolution story.','专名通常大写并斜体；作为历史名称，使用时应留意分类史变迁。','标签指向早期已灭绝马类，体现古生物学义。'),M('Eohippus is a modern living breed of large domestic horse used for racing.','Eohippus was an extinct early equid, not a modern living breed of large domestic horse used for racing.','Eohippus 是早期灭绝马类，不是现代竞赛马品种。'),[Q('eohippus',1,1,'Eohippus is associated with?','an extinct early relative in the horse family','a modern racing car','a living species of tropical fish','Eohippus 是早期已灭绝马科动物名称。'),Q('eohippus',2,1,'The name Eohippus is commonly glossed as?','dawn horse','equatorial bird','stone shield','词名由“黎明”和“马”组成。'),Q('eohippus',3,1,'A fossil museum might discuss Eohippus in an exhibit about?','the evolution of horses','the invention of escalators','the history of printing photographs','始祖马相关化石用于讨论马类演化。'),Q('eohippus',4,1,'Which description is most accurate?','an early extinct equid, historically called a dawn horse','a present-day domestic horse breed','a tool used for engraving','该词指灭绝的早期马类，不是工具或现代品种。')]);
P('eon','eon 借自希腊语 aiōn“时代、漫长时期”，可泛指极长时间，也指地质年代中的最大时间单位。',C('eon.s1','地质学','The rock layer formed an eon before the valley’s present rivers appeared, according to the geological dating summarized on the museum panel.','博物馆展板总结的地质测年显示，这层岩石形成于山谷现有河流出现之前一个极漫长的地质年代。','The rock layer formed an eon before the valley’s present rivers appeared / according to the geological dating / summarized on the museum panel.','普通用法常作夸张性长时间；地质学中 eon 是专门时间单位。','岩层与现有河流相隔极久，符合漫长时期义。'),M('The rock layer formed an eon ago, just five minutes before the river appeared.','The rock layer formed an eon ago, long before the river appeared.','五分钟与 eon 表示的极长时间矛盾。'),[Q('eon',1,1,'If someone says “I haven’t seen you in eons,” they mean?','it has been an extremely long time','they met five minutes ago','they have never learned your name','eon 常泛指漫长到仿佛无尽的时间。'),Q('eon',2,1,'In geology, an eon is?','a major division of geological time','a unit for measuring room width','the name of a small fossil shell','地质 eon 是大型地质时间单位。'),Q('eon',3,1,'Choose the natural phrase.','ages or eons ago','eons of one second','one eon of lunch','eon 与漫长年代搭配自然。'),Q('eon',4,1,'The project seemed to take eons. This is likely?','an informal exaggeration about a very long wait','a precise statement that it took one geological period','a claim that the project never began','口语中 eons 可以夸张表示等候特别久。')]);
P('ephemeral','ephemeral 借自希腊语 ephēmeros“只持续一天”，现代指存在或流行时间很短。',C('ephemeral.s1','网络文化','The dance became an ephemeral online trend: millions copied it for a week, then viewers moved on to a completely different challenge.','这种舞蹈只是昙花一现的网络潮流：数百万人模仿了一周，随后观众便转向完全不同的挑战。','The dance became an ephemeral online trend / millions copied it for a week / then viewers moved on to a completely different challenge.','ephemeral 常修饰 beauty、trend、existence 等，突出短暂。','热度只维持一周，符合 ephemeral。'),M('The ephemeral monument survived unchanged for ten thousand years and is still permanent.','The enduring monument survived unchanged for ten thousand years and is still permanent.','延续万年且永久保存的事物并非短暂。'),[Q('ephemeral',1,1,'An ephemeral fashion is?','popular only for a short time','unchanged for centuries','impossible to see','ephemeral 表示转瞬即逝或短期存在。'),Q('ephemeral',2,1,'Which thing is most clearly ephemeral?','a viral joke that disappears from attention in days','a mountain range lasting millions of years','a permanent legal record','几天后失去关注的笑话是短暂现象。'),Q('ephemeral',3,1,'Choose the closest opposite of ephemeral.','lasting','brief','fleeting','lasting 表示持久，与 ephemeral 相反。'),Q('ephemeral',4,1,'The poet calls beauty ephemeral to emphasize that it?','does not last forever','can be measured in kilograms','is easy to manufacture','ephemeral 突出美的短暂易逝。')]);
P('epicenter','epicenter 由 epi-“在……之上”与 center“中心”构成，地震学中指震源正上方的地表位置。',C('epicenter.s1','地震报道','Although the epicenter lay offshore, the strongest shaking occurred inland where soft sediment amplified the earthquake waves.','尽管震中位于近海，最强烈的震动却发生在内陆，因为松软沉积物放大了地震波。','Although the epicenter lay offshore / the strongest shaking occurred inland / where soft sediment amplified the earthquake waves.','名词；不要与地下岩层中的震源 hypocenter 混为一谈。','近海位置指地表的震中，和震源深度有别。'),M('The report located the epicenter deep beneath the crust, directly at the underground point where the rupture began.','The report located the hypocenter deep beneath the crust, directly at the underground point where the rupture began.','地下破裂起点是震源 hypocenter；epicenter 是其地表正上方位置。'),[Q('epicenter',1,1,'The epicenter of an earthquake is?','the surface point above where it began underground','the deepest point in the ocean','the place where aftershocks always end','震中是地表位于地下震源正上方的点。'),Q('epicenter',2,1,'A map marks the epicenter offshore. This identifies?','the earthquake’s surface location','the exact height of every wave','the direction of the nearest road','地图上的震中标记是地表位置。'),Q('epicenter',3,1,'Which term names the underground starting point, unlike epicenter?','hypocenter','equator','epidermis','hypocenter 指地下震源，epicenter 指地表对应点。'),Q('epicenter',4,1,'A news story uses epicenter figuratively for?','the central place where a major event is concentrated','the edge of an ordinary object','a type of moving staircase','引申义 epicenter 可指重大事件的中心区域。')]);
P('epidermis','epidermis 来自希腊语 epi“在……上”与 derma“皮肤”，指动物皮肤或植物表面的外层。',C('epidermis.s1','植物学','A waxy layer on the leaf epidermis slowed water loss, while tiny openings still allowed gases to move between the leaf and air.','叶片表皮上的蜡质层减慢了水分流失，而微小气孔仍允许叶片与空气交换气体。','A waxy layer on the leaf epidermis slowed water loss / while tiny openings still allowed gases to move / between the leaf and air.','植物学中 epidermis 指植物表面保护层；人体义为皮肤外层。','句中明确是叶片外层，符合植物表皮义。'),M('The epidermis is the deepest bone marrow inside a leaf.','The epidermis is the outermost protective layer on a leaf.','epidermis 是表面外层而非骨髓或内部骨组织。'),[Q('epidermis',1,1,'The epidermis of human skin is?','its outermost layer','the deepest layer of muscle','a type of joint','epidermis 是皮肤最外层。'),Q('epidermis',2,1,'A botanist examines the epidermis of a leaf to study?','its outer surface layer','the roots of a nearby tree','a bird’s feathers','植物叶片也有表皮层。'),Q('epidermis',3,1,'The parts epi- and dermis suggest?','a layer on or at the skin surface','a sound inside a cave','a time before sunrise','epi- 表示在上，dermis 与皮肤有关。'),Q('epidermis',4,1,'A scrape removes part of the epidermis. It affects?','the outer skin layer','the person’s entire skeleton','the inner ear only','擦伤可能破坏表皮这一外层。')]);
P('epigram','epigram 源自希腊语 epigramma“题写、铭刻”，经拉丁语进入英语，现指简短、机智而有力的警句。',C('epigram.s1','文学','The editor chose one epigram for the chapter opening: “A map can show the road, but not the courage to take it.”','编辑选了一句警句作为章节开头：“地图能指出道路，却指出不了踏上道路所需的勇气。”','The editor chose one epigram for the chapter opening / “A map can show the road / but not the courage to take it.”','可数名词，通常短小凝练，常带机智或讽刺意味。','一句简洁、有思想锋芒的话符合 epigram。'),M('The editor called a 900-page manual with no memorable lines an epigram.','The editor called the short, pointed line on the cover an epigram.','冗长且无警句的手册不是简短机智的 epigram。'),[Q('epigram',1,1,'An epigram is usually?','a brief, pointed, often witty statement','a long collection of laboratory tables','a spoken word with no meaning','epigram 是简短而有力、常带机智的表达。'),Q('epigram',2,1,'Which line is most like an epigram?','“A closed mind has no room for a new idea.”','“The office is located on the third floor.”','“Please submit the form by Tuesday.”','第一句简短机智并表达观点。'),Q('epigram',3,1,'An epigram may be used to?','express an idea memorably in few words','list every detail in a report','replace a whole dictionary','警句以精练方式令人记住一个观点。'),Q('epigram',4,1,'The adjective “epigrammatic” would best describe?','a concise and sharply phrased remark','a paragraph with no punctuation','a silent musical instrument','epigrammatic 指警句式的精练表达。')]);
P('episodic','episodic 由 episode 加 -ic 构成，可指间歇发生，也可指由相对独立片段组成。',C('episodic.s2','影视叙事','The series is episodic rather than tightly plotted: each installment follows a different detective case, although the same lead characters return.','这部剧采用单元式结构而非紧密连贯的主线：每集讲述不同的侦探案件，但主角始终相同。','The series is episodic rather than tightly plotted / each installment follows a different detective case / although the same lead characters return.','s2 常描述叙事由彼此相对独立的 episodes 构成。','每集故事独立、人物重复出现，体现片段式叙事。'),M('The episodic novel followed one uninterrupted event with no separate incidents or chapters.','The continuous novel followed one uninterrupted event with no separate incidents or chapters.','没有分段事件且连续推进的故事不属于片段式 episodic 结构。'),[Q('episodic',1,1,'An episodic illness occurs?','in separate periods rather than continuously','at exactly the same intensity every second','only in a fictional story','普通义 episodic 可指间歇发生。'),Q('episodic',2,2,'An episodic television series often has?','separate stories in different installments','one unbroken scene with no episode divisions','no recurring characters or stories','叙事义强调各集相对独立。'),Q('episodic',3,1,'Choose the closest opposite of episodic when describing symptoms.','constant','intermittent','occasional','constant 表示持续，与间歇相反。'),Q('episodic',4,2,'A novel told through separate incidents is?','episodic','equilateral','environmental','由独立事件构成的叙事可称 episodic。')]);
P('epistemology','epistemology 由希腊语 epistēmē“知识”与 logos“研究、论述”构成，指哲学中对知识及其根据的研究。',C('epistemology.s1','哲学','The seminar in epistemology asked whether a reliable memory is enough to count as knowledge when no independent evidence supports it.','认识论研讨课探讨：当没有独立证据支持时，可靠记忆是否足以构成知识。','The seminar in epistemology asked whether a reliable memory is enough / to count as knowledge / when no independent evidence supports it.','不可数学科名词，常接 about knowledge、evidence、justification 等话题。','讨论何为知识及其证成根据，正是认识论的研究对象。'),M('Epistemology studies the chemical composition of stars, not knowledge or evidence.','Astronomy studies the chemical composition of stars, not knowledge or evidence.','星体化学组成属天文学；epistemology 研究知识和认识依据。'),[Q('epistemology',1,1,'Epistemology is the branch of philosophy that studies?','knowledge and how it can be justified','the motion of escalators','the naming of horse breeds','认识论研究知识的性质及其证成方式。'),Q('epistemology',2,1,'A question in epistemology might ask?','What counts as evidence for knowing a claim?','How many steps does a staircase have?','Which paint dries fastest on wood?','何种证据能构成知识是认识论问题。'),Q('epistemology',3,1,'The Greek element epistēmē refers to?','knowledge','skin','a horse','epistēmē 是“知识”，构成 epistemology 的前半部分。'),Q('epistemology',4,1,'A researcher in epistemology would most likely examine?','whether belief and evidence amount to knowledge','how a leaf’s epidermis grows','how to build a market stall','信念、证据与知识的关系是认识论主题。')]);
P('epithet','epithet 源自希腊语 epitheton“附加的、称述的”，指附在姓名或名词上的描述性称号或短语。',C('epithet.s1','文学评论','The biographer explains that “the Iron Chancellor” was an epithet attached to Bismarck, reflecting how contemporaries viewed his political style.','传记作者解释，“铁血宰相”是附加在俾斯麦名字上的称号，反映了同时代人对其政治风格的看法。','The biographer explains that “the Iron Chancellor” was an epithet attached to Bismarck / reflecting how contemporaries viewed / his political style.','可数名词，描述性 epithet 可褒可贬，也可形成固定称号。','短语附加于人物姓名并概括特征，符合此义。'),M('“The Iron Chancellor” is an epithet for Bismarck, but it contains no description or characterization.','“The Iron Chancellor” is a descriptive epithet for Bismarck, characterizing his political image.','该称号明显含有对人物特征的描述，不可能没有 characterization。'),[Q('epithet',1,1,'An epithet attached to a person’s name is?','a descriptive title or phrase','a list of the person’s relatives','a measurement of the person’s height','epithet 是附加在人名上的描述性称号或短语。'),Q('epithet',2,1,'Which phrase functions as an epithet?','“the Great” in “Catherine the Great”','the date 1762 in a timeline','the word “and” in a sentence','the Great 是描述性称号。'),Q('epithet',3,1,'An insulting epithet is?','a derogatory label used for someone','a respectful job reference','a neutral map symbol','epithet 也可为侮辱性称呼。'),Q('epithet',4,1,'A writer uses an epithet mainly to?','characterize someone in a compact phrase','report an exact temperature','show how to fold paper','称号以短语概括人物特征。')]);
P('epitome','epitome 源自希腊语 epitomē“删节、摘录”，现代常指最典型、最完美地体现某特质的人或事物。',C('epitome.s1','人物描写','In the coach’s view, Amina was the epitome of patience: she listened carefully, corrected each mistake calmly, and never mocked a beginner.','在教练看来，阿米娜是耐心的典范：她认真倾听、平静纠正每个错误，从不嘲笑初学者。','In the coach’s view, Amina was the epitome of patience / she listened carefully / corrected each mistake calmly / and never mocked a beginner.','常用 the epitome of + 抽象品质，指典型体现者。','她的行为集中体现耐心，符合“典范、缩影”义。'),M('Amina was the epitome of patience because she interrupted everyone and shouted at beginners.','Amina was the epitome of impatience because she interrupted everyone and shouted at beginners.','打断和呵斥表现不耐烦，应把 patience 改为 impatience。'),[Q('epitome',1,1,'The epitome of courage is?','a perfect example of courage','a brief spelling list','a small amount of courage with no example','epitome 指某种品质最典型的体现。'),Q('epitome',2,1,'If a team is the epitome of cooperation, its members?','work together exceptionally well','refuse to share any information','never meet one another','该队完美体现合作精神。'),Q('epitome',3,1,'Choose the natural phrase.','the epitome of elegance','an epitome from elegance','the epitome to elegant','常用结构是 the epitome of。'),Q('epitome',4,1,'Calling a building “the epitome of modern design” means it?','perfectly represents modern design','is the first building ever made','cannot be described as design','此处表示建筑是现代设计的典范。')]);
P('epitomise','epitomise 是 epitomize 的英式 -ise 拼法，意为集中体现某种典型品质或特征。',C('epitomise.s1','社会观察','For many residents, the old market epitomises neighborhood life because generations have met there to trade, eat, and exchange news.','对许多居民而言，老市场集中体现了社区生活，因为好几代人都在那里交易、用餐和交换消息。','For many residents, the old market epitomises neighborhood life / because generations have met there / to trade, eat, and exchange news.','英式常拼 epitomise；动词及物，宾语常为 quality、period、idea 等。','市场概括体现社区生活的典型面貌。'),M('The empty, unused hall epitomises lively neighborhood life, although nobody has visited it for years.','The crowded, active market epitomises lively neighborhood life, although nobody has visited the empty hall for years.','多年无人使用的空厅不能典型体现活跃社区生活。'),[Q('epitomise',1,1,'To epitomise a quality is to?','represent it as a typical or ideal example','hide it from every observer','measure it with a ruler','epitomise 表示集中体现。'),Q('epitomise',2,1,'“Her actions epitomise fairness” means they?','are a clear example of fairness','make fairness impossible to define','have nothing to do with fairness','她的行为是公平的典型体现。'),Q('epitomise',3,1,'Epitomise is commonly the British spelling of?','epitomize','epidermize','epigramise','epitomize 是常见美式拼法。'),Q('epitomise',4,1,'Choose the natural construction.','This building epitomises the city’s history.','This building epitomises with the city’s history.','This building epitomises to the city’s history.','及物动词 epitomise 后直接接体现的对象。')]);
P('epitomize','epitomize 由 epitome 加动词后缀 -ize 构成；可指典型体现，也可指概括、浓缩要点。',C('epitomize.s1','人物刻画','The calm dispatcher epitomizes the team’s professionalism: even as the storm closed roads, she gave callers clear instructions.','这位冷静的调度员体现了团队的专业精神：即使暴风雨封路，她仍向来电者清楚说明应对步骤。','The calm dispatcher epitomizes the team’s professionalism / even as the storm closed roads / she gave callers clear instructions.','及物动词后接被体现的品质；英式常写 epitomise。','冷静和清晰指导是专业精神的典型表现。'),M('The dispatcher epitomizes professionalism by giving confused callers false directions and shouting at them.','The dispatcher epitomizes unprofessionalism by giving confused callers false directions and shouting at them.','提供错误指引并对来电者大喊表现不专业。'),[Q('epitomize',1,1,'A person who epitomizes kindness?','is a particularly clear example of kindness','cannot recognize kindness','works only with epitaphs','epitomize 表示典型体现。'),Q('epitomize',2,1,'To epitomize a long argument can mean to?','summarize its central point','add every missing paragraph','translate it into a different alphabet','该词也可表示概括、浓缩要点。'),Q('epitomize',3,1,'Choose the natural phrase.','epitomize the spirit of the age','epitomize into the spirit of the age','epitomize to the spirit of the age','及物结构直接接 the spirit。'),Q('epitomize',4,1,'Which behavior epitomizes carelessness?','leaving the laboratory door unlocked after a safety warning','checking each lock before leaving','writing down every result accurately','忽视安全警告、未锁实验室体现粗心。')]);
P('equality','equality 由 equal 加 -ity 构成，可指权利、地位上的平等，也可指数量或程度相等。',C('equality.s1','公共政策','The charter guarantees equality before the law, so the same appeal process applies to officials and residents alike.','章程保障法律面前人人平等，因此官员与居民适用同一申诉程序。','The charter guarantees equality before the law / so the same appeal process applies / to officials and residents alike.','义项 s1 指权利或地位平等；常见 equality between/of。','双方适用相同程序，体现法律平等。'),M('The policy guarantees equality by giving one group a hearing and denying every other group access to the same process.','The policy violates equality by giving one group a hearing and denying every other group access to the same process.','只允许一组申诉、排斥他组属于不平等。'),[Q('equality',1,1,'Equality before the law means?','people receive the same legal treatment','one person has no legal rights','every case has the same result','法律平等要求适用相同规则，不保证每案结果相同。'),Q('equality',2,2,'In mathematics, equality between two amounts means they are?','the same in value','both unknown forever','different by definition','数量义 equality 表示数值相等。'),Q('equality',3,1,'Which phrase is natural?','equality of opportunity','equalnessly opportunity','equality to the law before','equality of opportunity 是常见搭配。'),Q('equality',4,1,'A campaign for gender equality seeks?','equal rights and opportunities across genders','to remove all differences in language','to make every person choose the same job','性别平等运动旨在保障平等权利和机会。')]);
P('equatorial','equatorial 由 equator 加 -ial 构成，描述位于赤道附近或与赤道有关的事物。',C('equatorial.s1','气候','Equatorial forests receive warmth throughout the year, but rainfall and altitude still create substantial differences between local habitats.','赤道森林全年温暖，但降雨和海拔仍会造成当地栖息地之间显著差异。','Equatorial forests receive warmth throughout the year / but rainfall and altitude / still create substantial differences between local habitats.','形容词，常修饰 region、climate、forest、current 等。','森林位于赤道附近，符合 equatorial。'),M('The equatorial station stood near the North Pole, thousands of kilometers from the equator.','The polar station stood near the North Pole, thousands of kilometers from the equator.','北极附近不属于赤道地区。'),[Q('equatorial',1,1,'An equatorial region lies near?','the equator','the North Pole','the center of the Moon','equatorial 指赤道附近。'),Q('equatorial',2,1,'An equatorial climate is often associated with?','warm conditions near the equator','permanent polar night','the center of a solid rock','该形容词描述赤道地区的气候特征。'),Q('equatorial',3,1,'Choose the natural phrase.','equatorial current','equatorially equator','equatoriality current','equatorial current 是自然搭配。'),Q('equatorial',4,1,'A map of equatorial countries would focus on countries?','near the line around Earth halfway between the poles','inside the Arctic Circle only','on the Moon','赤道位于两极之间，附近国家属赤道地区。')]);
P('equestrian','equestrian 经法语源自拉丁语 equestris“骑兵的”，关联 eques“骑士”和 equus“马”。',C('equestrian.s1','运动','The equestrian event was postponed because the course surface had frozen, creating unsafe conditions for both riders and horses.','由于赛道表面结冰、对骑手和马匹都不安全，马术项目被推迟。','The equestrian event was postponed / because the course surface had frozen / creating unsafe conditions for both riders and horses.','形容词修饰 sport、event、skill 等；也可作名词指骑手。','骑手与马参加的赛事属于马术运动。'),M('The equestrian contest featured swimmers racing through a pool without horses or riding.','The swimming contest featured swimmers racing through a pool without horses or riding.','没有马匹或骑术的游泳比赛不是 equestrian 赛事。'),[Q('equestrian',1,1,'An equestrian sport involves?','horse riding','deep-sea diving','table-tennis scoring','equestrian 与骑马、马术有关。'),Q('equestrian',2,1,'An equestrian center is a place where people may?','learn to ride and care for horses','repair escalators','study the skin’s outer layer','马术中心提供骑马与马匹照护活动。'),Q('equestrian',3,1,'Choose the natural phrase.','equestrian competition','equestrian competitionless','equestrially horse','equestrian 可修饰 competition。'),Q('equestrian',4,1,'A person described as an equestrian is most likely?','a rider or someone involved in horse riding','a person who studies earthquakes','a writer of epigrams only','名词 equestrian 也指骑手。')]);
P('equilateral','equilateral 源自拉丁语 aequilateralis，由 aequi-“相等”与 latus“边”构成，指各边等长的。',C('equilateral.s1','几何','The class proved that the triangular sign was equilateral by measuring all three sides and finding the same length on each.','全班测量三角形标志的三条边，发现长度相同后证明它是等边的。','The class proved that the triangular sign was equilateral / by measuring all three sides / and finding the same length on each.','equilateral triangle 是“等边三角形”；不等于 equiangular 的等角。','三条边长度相同是等边定义。'),M('The triangle was equilateral because it had three sides of different lengths.','The triangle was scalene because it had three sides of different lengths.','三边长度不同是 scalene（不等边），不是 equilateral。'),[Q('equilateral',1,1,'An equilateral triangle has?','three sides of equal length','one curved side','four sides of unequal length','equilateral triangle 的三条边等长。'),Q('equilateral',2,1,'The prefix equi- in equilateral suggests?','equality','distance','uncertainty','equi- 表示相等。'),Q('equilateral',3,1,'Which shape is equilateral?','a triangle with all sides measuring 5 cm','a triangle with sides of 3, 4, and 6 cm','a circle with no sides','三边都是五厘米的三角形等边。'),Q('equilateral',4,1,'Equilateral describes equality of?','side lengths','temperature readings','the number of vertices in every shape','该词描述边长相等。')]);
P('equilibrium','equilibrium 由拉丁语 aequus“相等”与 libra“天平、平衡”相关成分构成，指相互作用力量或数量达到稳定平衡。',C('equilibrium.s1','物理','The hanging sign reached equilibrium when the two cables pulled with equal force in opposite directions and it stopped swinging.','两根缆绳以相等力量向相反方向拉住吊牌后，吊牌停止摇晃并达到平衡。','The hanging sign reached equilibrium / when the two cables pulled with equal force / in opposite directions and it stopped swinging.','常用 in equilibrium、reach equilibrium；物理和经济等领域均有此义。','相反力量相抵后系统稳定，体现 equilibrium。'),M('The sign was in equilibrium while one cable pulled hard and the other cable exerted no force.','The sign was out of equilibrium while one cable pulled hard and the other cable exerted no force.','受力不平衡时吊牌会移动，不能说处于平衡。'),[Q('equilibrium',1,1,'A system in equilibrium has?','opposing forces or amounts balanced','every force pointing in one direction','no measurable quantities at all','equilibrium 指相互作用力量或数量达到平衡。'),Q('equilibrium',2,1,'A market reaches equilibrium when?','supply and demand balance at a stable price','all goods disappear from every shop','prices change unpredictably every minute','供求达到平衡时市场可能处于均衡。'),Q('equilibrium',3,1,'Choose the natural phrase.','maintain equilibrium','equilibrium at unbalanced force','equilibriality maintain','maintain equilibrium 表示保持平衡。'),Q('equilibrium',4,1,'A gymnast regains equilibrium after a turn by?','restoring balance and steady posture','accelerating into another fall','closing both eyes permanently','equilibrium 也可指身体平衡状态。')]);
P('equinox','equinox 借自拉丁语 aequinoctium，由 aequus“相等”与 nox“夜晚”构成，指昼夜接近等长的时点。',C('equinox.s1','天文学','On the spring equinox, the museum’s sky map showed the Sun crossing the celestial equator, marking the seasonal transition in the Northern Hemisphere.','在春分这天，博物馆星图显示太阳穿过天球赤道，标志着北半球季节转换。','On the spring equinox / the museum’s sky map showed the Sun crossing the celestial equator / marking the seasonal transition in the Northern Hemisphere.','一年通常有春分和秋分；昼夜长度接近相等，而非每处严格完全相等。','太阳穿越天球赤道的天文事件是 equinox。'),M('The autumn equinox occurs when the Sun is farthest north of the celestial equator and daylight lasts longest.','The summer solstice occurs when the Sun is farthest north of the celestial equator and daylight lasts longest.','太阳偏北最远、白昼最长对应夏至 solstice，不是秋分。'),[Q('equinox',1,1,'An equinox occurs around the time when?','day and night are nearly equal in length','the Moon disappears forever','the Sun stops moving across the sky','equinox 时昼夜时长接近相等。'),Q('equinox',2,1,'The spring equinox marks?','the Sun’s crossing of the celestial equator','the first day of every lunar month','the moment Earth leaves its orbit','春分对应太阳穿越天球赤道。'),Q('equinox',3,1,'How many equinoxes occur in a typical year?','two','one hundred','none','通常一年有春分和秋分两个分点。'),Q('equinox',4,1,'Which word is often contrasted with equinox in seasonal astronomy?','solstice','epigram','epidermis','solstice 是至点，与分点相区别。')]);
P('equitable','equitable 来自 equity 加 -able，最终源自拉丁语 aequus“平、公正”，表示公平合理，不必意味着人人得到相同结果。',C('equitable.s1','薪酬制度','The new pay policy was considered equitable because it used transparent criteria and allowed employees with comparable duties to appeal.','新薪酬政策被认为公平合理，因为它采用透明标准，并允许职责相近的员工提出申诉。','The new pay policy was considered equitable / because it used transparent criteria / and allowed employees with comparable duties to appeal.','equitable 常修饰 treatment、distribution、decision；强调公平而非机械相同。','透明标准和申诉机制体现公平处理。'),M('The allocation was equitable because managers received everything while every other worker received nothing.','The allocation was inequitable because managers received everything while every other worker received nothing.','完全偏向管理层、不给其他员工份额显然不公平。'),[Q('equitable',1,1,'An equitable decision is?','fair and reasonable','necessarily identical for every person','based on an unexplained preference','equitable 强调公平合理。'),Q('equitable',2,1,'An equitable distribution may give people?','different shares when their needs or circumstances differ fairly','exactly the same result in every possible case','nothing regardless of their situation','公平分配可以根据合理差异调整份额。'),Q('equitable',3,1,'Choose the natural phrase.','equitable access to services','equitablely service access','equitable access by servicesness','equitable access 是常见搭配。'),Q('equitable',4,1,'The closest opposite of equitable is?','unfair','impartial','just','unfair 与 equitable 的公平义相反。')]);
P('equivalence','equivalence 由 equivalent 加 -ence 构成，指价值、数量、意义或功能上的相等或对应。',C('equivalence.s1','翻译','The translator checked the equivalence of the two phrases in context, since a word-for-word match would have sounded unnatural in the target language.','译者在语境中核对两个短语是否对应，因为逐字匹配在目标语言里会显得不自然。','The translator checked the equivalence of the two phrases in context / since a word-for-word match / would have sounded unnatural in the target language.','不可数名词，常用 equivalence between A and B 或 functional equivalence。','核对表达在语境中的对应功能，符合此义。'),M('The two measurements showed equivalence because one was 10 centimeters and the other was 90 meters.','The two measurements showed no equivalence because one was 10 centimeters and the other was 90 meters.','10厘米与90米并不相等，不能说两者等价。'),[Q('equivalence',1,1,'Equivalence between two amounts means they?','are equal in value or effect','have no relation of any kind','must use the same letters','equivalence 指价值、作用等方面相等或对应。'),Q('equivalence',2,1,'A translator seeks equivalence when?','finding a phrase with the same meaning or function','copying words that mean the opposite','removing the original sentence','翻译中的对应关注意义或功能相近。'),Q('equivalence',3,1,'Choose the natural phrase.','the equivalence between the two systems','the equivalence at the systems between','equivalenceful systems between','常用 equivalence between。'),Q('equivalence',4,1,'A scientific conversion table shows?','the equivalence of measurements in different units','how to make every measurement inaccurate','the shape of a laboratory building','换算表展示不同单位之间的等值关系。')]);
P('equivocal','equivocal 经晚期拉丁语 aequivocus“同音、可有相等解释”而来，指含糊、可作多种理解，也可指态度不明确。',C('equivocal.s1','记者会','Asked whether the firm would close the plant, the spokesperson gave an equivocal answer that neither confirmed nor ruled out the plan.','被问及公司是否会关闭工厂时，发言人给出含糊回答，既未确认也未排除该计划。','Asked whether the firm would close the plant / the spokesperson gave an equivocal answer / that neither confirmed nor ruled out the plan.','常修饰 answer、statement、evidence；与 unequivocal“明确无疑”相对。','回答没有明确立场、留下多种解释，符合 equivocal。'),M('The spokesperson gave an equivocal answer: “Yes, the plant will close on 1 June,” with no room for doubt.','The spokesperson gave an unequivocal answer: “Yes, the plant will close on 1 June,” with no room for doubt.','日期明确且毫无疑问的回答是 unequivocal。'),[Q('equivocal',1,1,'An equivocal statement is?','ambiguous or open to more than one interpretation','perfectly clear and impossible to misunderstand','written in a foreign alphabet','equivocal 表示含糊或有多种解读。'),Q('equivocal',2,1,'Which response is equivocal?','“We may act, but we have not ruled anything out.”','“The meeting begins at exactly 3:00 p.m.”','“The answer is no, without exception.”','前者未明确承诺，留下多种可能。'),Q('equivocal',3,1,'Choose the closest opposite of equivocal.','unequivocal','ambiguous','vague','unequivocal 表示明确无疑。'),Q('equivocal',4,1,'Equivocal evidence would make a researcher?','uncertain because it supports multiple readings','certain of one conclusion beyond doubt','unable to find any data at all','多种解释的证据会导致结论不确定。')]);
P('eradication','eradication 来自 eradicate 加 -ion；eradicate 源自拉丁语 eradicare“连根拔除”，比喻彻底消灭。',C('eradication.s1','公共卫生','The eradication campaign combined vaccination, disease surveillance, and rapid reporting so that remaining cases could be contained before transmission resumed.','根除行动结合疫苗接种、疾病监测和快速报告，以便在传播恢复前控制残余病例。','The eradication campaign combined vaccination, disease surveillance, and rapid reporting / so that remaining cases could be contained / before transmission resumed.','不可数名词，常用于 eradicate a disease、eradication of disease/poverty。','采取措施消除疾病及残余传播，符合彻底根除义。'),M('The eradication of the infection was successful even though new cases continued to spread every day.','The control of the infection improved even though new cases continued to spread every day.','病例每天继续传播表示尚未根除；control 可表示控制但不等于清零。'),[Q('eradication',1,1,'The eradication of a disease means?','its complete removal','a small increase in its symptoms','a new method of diagnosing it','eradication 表示彻底消灭。'),Q('eradication',2,1,'Which measure contributes to pest eradication?','eliminating the remaining breeding sites','moving the pests to another room','counting pests without taking action','清除繁殖地点有助彻底消灭害虫。'),Q('eradication',3,1,'Choose the natural phrase.','the eradication of polio','the eradication at a disease','eradicationful of polio','常用 eradication of + 被消灭对象。'),Q('eradication',4,1,'Eradication differs from temporary control because eradication aims to?','remove the problem completely','reduce it for one afternoon only','measure how often it occurs','根除目标是彻底消除而非暂时控制。')]);
P('ere','ere 是古英语 ǣr“更早、以前”的文学性遗留形式，作介词或连词，意为在……之前。',C('ere.s1','文学阅读','“Leave ere dawn,” the old captain ordered, meaning the crew should depart before the first light appeared over the harbor.','“黎明前离开，”老船长命令道，意思是船员应在港口天亮之前出发。','“Leave ere dawn,” the old captain ordered / meaning the crew should depart / before the first light appeared over the harbor.','文学或古雅用语；现代普通表达通常用 before。','句中 ere dawn 等于 before dawn。'),M('The captain ordered the crew to leave ere dawn, meaning they should depart after sunrise.','The captain ordered the crew to leave after dawn, meaning they should depart after sunrise.','ere 表示“在……之前”，不能解释成日出以后。'),[Q('ere',1,1,'In literary English, ere means?','before','because','beneath','ere 是古雅用法，意为 before。'),Q('ere',2,1,'“Ere the bell rang” means?','before the bell rang','after the bell rang','while the bell was being repaired','ere the bell rang 等于 before the bell rang。'),Q('ere',3,1,'Where is ere most likely to appear today?','in poetry or deliberately old-fashioned writing','in ordinary technical instructions only','as a plural noun for ears','ere 带文学或古雅色彩。'),Q('ere',4,1,'Choose the closest modern replacement: “Return ere sunset.”','Return before sunset.','Return because of sunset.','Return beneath the sun.','此处 ere 可由 before 替换。')]);
P('erection','erection 源自拉丁语 erigere“竖起、建造”，由 erect 加 -ion 构成，指建筑物的建造或某物竖立起来。',C('erection.s1','建筑工程','The erection of the temporary tower took two days, after which engineers checked each joint before allowing workers to climb it.','临时塔架用了两天建成；随后工程师逐个检查接头，才允许工人攀登。','The erection of the temporary tower took two days / after which engineers checked each joint / before allowing workers to climb it.','义项 s1 指搭建、建造；常用 erection of a building/structure。','塔架搭建及安全检查对应建造义。'),M('The erection of the tower was completed by taking it apart and removing every support.','The dismantling of the tower was completed by taking it apart and removing every support.','拆除不是 erection；dismantling 与行为一致。'),[Q('erection',1,1,'The erection of a building is?','the process of putting it up','the process of painting a portrait','the act of digging a well only','erection 可指建筑物的建造。'),Q('erection',2,1,'A temporary fence’s erection involves?','setting the fence up','removing every fence panel','measuring the wind speed','erection 在此指搭建围栏。'),Q('erection',3,1,'Choose the natural phrase.','the erection of a bridge','the erection to a bridge','the erectness of building up','常用 erection of + 建筑或结构。'),Q('erection',4,1,'The crew completed the erection before the opening. This means they?','built or put up the structure','tore down the structure','canceled the opening','erection 指结构搭建完成。')]);
P('erosion','erosion 经法语源自拉丁语 erodere“啃蚀、侵蚀”，指土石被风水磨损，也可比喻价值或信任逐渐削弱。',C('erosion.s2','社会信任','Repeated unexplained fee increases led to an erosion of trust between the residents and the housing association.','反复出现且未作解释的费用上涨，逐渐侵蚀了居民与住房协会之间的信任。','Repeated unexplained fee increases led to an erosion of trust / between the residents and the housing association.','常用 erosion of + 土壤、海岸、信任、权利等；引申义强调渐进损失。','信任被逐步削弱，符合 s2。'),M('The erosion of public trust strengthened confidence in the association, although residents trusted it less each month.','The erosion of public trust weakened confidence in the association, although residents trusted it less each month.','信任减少会削弱信心，不能称为 strengthening。'),[Q('erosion',1,1,'The erosion of a coastline is?','the gradual wearing away of its land','the sudden construction of a new harbor','the measurement of ocean temperature','地理义指海岸被逐渐侵蚀。'),Q('erosion',2,2,'An erosion of trust means trust?','has gradually weakened','has increased immediately','has stayed untouched forever','比喻义表示信任逐渐削弱。'),Q('erosion',3,1,'Which force can cause soil erosion?','wind and running water','a printed dictionary','a still indoor lamp','风和流水能带走土壤。'),Q('erosion',4,2,'A policy may cause erosion of rights by?','slowly reducing protections people once had','granting everyone stronger protections','publishing a list of rights','权利保障逐渐减少体现引申义 erosion。')]);
P('erratically','erratically 由 erratic 加 -ly 构成；erratic 源自拉丁语 errare“漫游、偏离”，表示不规则地。',C('erratically.s1','设备运作','The old pump operated erratically, sometimes stopping for several minutes and then restarting without any change in the controls.','旧水泵运转不规律，有时停好几分钟，又在控制设置未变的情况下自行重启。','The old pump operated erratically / sometimes stopping for several minutes / and then restarting without any change in the controls.','副词修饰 operated；强调缺乏稳定模式，不是单纯速度快。','停机和重启没有规律，符合 erratically。'),M('The clock ran erratically because it kept exactly the same time every day without any variation.','The clock ran reliably because it kept exactly the same time every day without any variation.','每天准确且无变化属于稳定可靠，不是 erratic。'),[Q('erratically',1,1,'A machine that behaves erratically behaves?','in an irregular and unpredictable way','with perfect consistency','only when it is switched off','erratically 表示不规则、难预测地。'),Q('erratically',2,1,'Which driver is driving erratically?','one who repeatedly swerves and changes speed without reason','one who holds a steady lane and speed','one who parks safely and walks away','反复无故变速、变道表现不规律。'),Q('erratically',3,1,'Choose the natural sentence.','The signal flashed erratically during the storm.','The signal erratically was blue in color.','The signal was an erratically.','副词 erratically 修饰 flashed。'),Q('erratically',4,1,'If a pulse is recorded erratically, the readings are?','uneven and not following a steady pattern','identical at every moment','missing only because the paper is blue','记录无规律表示不稳定。')]);
P('erroneous','erroneous 源自拉丁语 erroneus，关联 errare“犯错、偏离”，表示错误的或建立在误解上的。',C('erroneous.s2','数据分析','The report relied on the erroneous assumption that every household had the same water use, so its demand forecast was too low.','报告依赖“每户用水量相同”这一错误假设，因此需求预测偏低。','The report relied on the erroneous assumption / that every household had the same water use / so its demand forecast was too low.','常修饰 assumption、belief、information、conclusion；含有判断或依据错误。','错误假设导致预测偏低，体现 s2。'),M('The erroneous calculation was correct to the last decimal and had been checked independently three times.','The accurate calculation was correct to the last decimal and had been checked independently three times.','精确且反复核实的计算不是 erroneous。'),[Q('erroneous',1,1,'An erroneous answer is?','incorrect','extremely polite','carefully hidden','erroneous 表示错误的。'),Q('erroneous',2,2,'An erroneous assumption is one that?','is based on a mistake','has been proven beyond doubt','is written in another language','erroneous 可修饰基于错误的假设。'),Q('erroneous',3,1,'Choose the closest opposite of erroneous.','accurate','mistaken','false','accurate 与 erroneous 相反。'),Q('erroneous',4,2,'A conclusion is erroneous if it?','follows from faulty information or reasoning','matches all reliable evidence','is never stated aloud','根据错误信息或推理得出的是 erroneous conclusion。')]);
P('erudite','erudite 源自拉丁语 eruditus“博学的”，来自 erudire“教育、教导”，字面有“脱去粗浅”的意思。',C('erudite.s1','学术讨论','The erudite historian cited tax records, private letters, and local songs to explain why the port’s population changed over three centuries.','这位博学的历史学家引用税务记录、私人信件和地方歌谣，解释港口人口在三百年间发生变化的原因。','The erudite historian cited tax records, private letters, and local songs / to explain why the port’s population changed / over three centuries.','形容学识渊博的人或著作；语体偏正式。','多种史料支持的深入解释体现其学识广博。'),M('The erudite scholar had never read a book, studied any subject, or learned anything about history.','The ignorant scholar had never read a book, studied any subject, or learned anything about history.','从未学习与博学相反，应使用 ignorant。'),[Q('erudite',1,1,'An erudite scholar is?','highly learned','unable to read','unwilling to answer any question','erudite 表示学识渊博。'),Q('erudite',2,1,'An erudite essay may contain?','carefully supported knowledge from wide reading','random claims with no evidence','only a shopping list','广泛阅读并有根据的知识体现博学。'),Q('erudite',3,1,'Choose the closest synonym of erudite.','scholarly','uninformed','careless','scholarly 与 erudite 都指学术、博学。'),Q('erudite',4,1,'Which person is most likely to be described as erudite?','a researcher who knows several fields in depth','a visitor who refuses to learn anything','a runner who misses the bus','跨领域深入掌握知识者可能被称作 erudite。')]);
P('escalator','escalator 是奥的斯电梯公司于 1900 年使用的商品名，由 escalade 与 elevator 中的 -ator 组合而来，指自动扶梯。',C('escalator.s1','交通设施','The station closed one escalator for repairs and directed passengers with luggage to the working lift near the north entrance.','车站关闭了一部自动扶梯维修，并引导带行李的乘客使用北入口附近可运行的电梯。','The station closed one escalator for repairs / and directed passengers with luggage / to the working lift near the north entrance.','可数名词，指有连续移动踏板的楼梯；与垂直电梯 lift/elevator 区分。','乘客被引导去使用电梯而非停运的移动楼梯。'),M('Passengers climbed the escalator while every step remained fixed and never moved.','Passengers climbed the ordinary stairs while every step remained fixed and never moved.','踏步固定不动的是普通楼梯，不是自动扶梯。'),[Q('escalator',1,1,'An escalator carries people between floors using?','steps that move continuously','a fixed ladder carried by hand','a rope pulled by passengers','自动扶梯依靠连续移动的踏板。'),Q('escalator',2,1,'Which is the safer choice for a wheelchair user?','a lift or elevator','an escalator with moving steps','a steep fixed ladder','轮椅使用者应选择电梯而非扶梯。'),Q('escalator',3,1,'Choose the natural phrase.','ride the escalator','swim the escalator','read the escalator as a book','常用 ride/take the escalator。'),Q('escalator',4,1,'The name escalator was historically coined from escalade and?','elevator','epidermis','equality','历史构词结合 escalade 与 elevator 的形式。')]);
P('escapist','escapist 由 escape 加 -ist 构成，可指通过幻想或娱乐逃避现实问题的人，也可作形容词修饰此类作品。',C('escapist.s1','文学评论','The reviewer called the novel escapist because its hero solved every real-world problem by entering a fantasy kingdom and never facing its consequences.','评论家称这部小说是逃避现实的作品，因为主人公一遇到现实问题就进入幻想王国，从不面对后果。','The reviewer called the novel escapist / because its hero solved every real-world problem / by entering a fantasy kingdom and never facing its consequences.','可作名词或形容词；此处修饰 novel，形容借幻想逃开现实。','作品让人物持续躲避现实难题，体现 escapist 特征。'),M('The escapist faced every difficult fact directly and refused all fantasy or distraction.','The realist faced every difficult fact directly and refused all fantasy or distraction.','直面现实、拒绝幻想体现 realist，不是逃避现实者。'),[Q('escapist',1,1,'An escapist avoids?','dealing with real problems by turning to fantasy or distraction','all forms of entertainment','every possible conversation','escapist 指借幻想或娱乐逃避现实。'),Q('escapist',2,1,'An escapist film is likely to?','offer an imaginative escape from ordinary worries','document every detail of a tax audit','avoid having any story','此形容词可修饰提供幻想性消遣的作品。'),Q('escapist',3,1,'Which person best fits the noun escapist?','someone who retreats into fantasy instead of addressing problems','a mechanic who repairs a broken lift','a judge who issues a clear ruling','逃进幻想逃避问题的人符合名词义。'),Q('escapist',4,1,'Choose the closest opposite of escapist in this context.','realist','dreamer','fantasist','realist 倾向面对现实，与 escapist 相对。')]);
P('escarpment','escarpment 源自法语 escarpement，关联 escarpe“陡坡”，最终与意大利语 scarpa“斜坡”有关。',C('escarpment.s1','地貌','The road follows the foot of the escarpment, where a long steep slope separates the plateau above from the lower plain.','道路沿着陡崖线下方延伸；这道长而陡的坡面把上方高原与下方平原分隔开。','The road follows the foot of the escarpment / where a long steep slope separates the plateau above / from the lower plain.','可数地貌名词，通常指延伸较长的陡坡或崖线。','高原和平原之间的长陡坡符合 escarpment。'),M('The hikers crossed an escarpment, a broad flat plain with no steep slope or change in level.','The hikers crossed a plain, a broad flat area with no steep slope or change in level.','没有高差的平坦地形是 plain，不是 escarpment。'),[Q('escarpment',1,1,'An escarpment is?','a long steep slope or cliff separating higher and lower land','a completely flat indoor floor','a shallow pond in a garden','escarpment 指长陡坡或崖线。'),Q('escarpment',2,1,'A plateau above an escarpment is?','higher than the land below the steep slope','under the ocean floor','the same as a moving staircase','陡崖线分隔不同高度地貌。'),Q('escarpment',3,1,'Which landscape might contain an escarpment?','a high plateau dropping sharply to a plain','a level meadow with no slope','a smooth indoor ceiling','高原边缘骤降到平原可形成 escarpment。'),Q('escarpment',4,1,'A geographer maps an escarpment to show?','a steep change in terrain elevation','a list of horse breeds','a change in spelling between variants','该地貌标示地势的陡然变化。')]);
P('eschatology','eschatology 由希腊语 eskhatos“最后的、终极的”与 -logy 构成，指宗教中关于死亡、审判及人类终局的教义研究。',C('eschatology.s1','宗教学','The course compares eschatology in several traditions, examining how each describes death, final judgment, and the ultimate destiny of humanity.','课程比较多个传统中的末世论，研究它们如何描述死亡、最后审判以及人类的最终归宿。','The course compares eschatology in several traditions / examining how each describes death, final judgment, / and the ultimate destiny of humanity.','不可数学科名词，属于神学或宗教研究。','课程讨论终极命运和最后审判，符合末世论。'),M('Eschatology is the study of present-day crop rotation, not religious beliefs about death or final destiny.','Agronomy is the study of crop production and soil management, not religious beliefs about death or final destiny.','作物生产属农学 agronomy；eschatology 讨论宗教终末教义。'),[Q('eschatology',1,1,'Eschatology studies religious ideas about?','death, judgment, and the final destiny of humanity','the construction of staircases','the outer layer of a leaf','eschatology 是关于死亡、审判与人类终局的神学研究。'),Q('eschatology',2,1,'A theologian studying the end of history is working in?','eschatology','epidermis','equestrian sport','末世论探讨历史终局与终极事件。'),Q('eschatology',3,1,'The element eschato- in eschatology relates to?','what is last or final','a moving step','equality of length','希腊词根指最后、终极。'),Q('eschatology',4,1,'Which topic belongs in an eschatology seminar?','beliefs about final judgment and the afterlife','how plants produce enzymes','how to repair an escalator','最后审判和来世属于末世论主题。')]);
P('eschew','eschew 经古法语 eschiver“躲避、避开”进入英语，最终源自日耳曼语族词根，意为有意避免或拒绝。',C('eschew.s1','写作原则','The journal asks contributors to eschew sensational claims and describe uncertain results cautiously, especially when the sample is small.','期刊要求投稿者避免耸人听闻的说法，在样本量较小时尤其要谨慎描述不确定结果。','The journal asks contributors to eschew sensational claims / and describe uncertain results cautiously / especially when the sample is small.','及物动词，后接习惯、做法或事物；语气较正式。','作者刻意避开夸张说法，符合 eschew。'),M('The journal eschewed sensational claims by filling its headline with the most exaggerated wording available.','The journal embraced sensational claims by filling its headline with the most exaggerated wording available.','使用最夸张措辞是 embrace 耸动说法，不是避开。'),[Q('eschew',1,1,'To eschew a habit is to?','deliberately avoid or give it up','practice it more frequently','measure how long it lasts','eschew 表示有意避开。'),Q('eschew',2,1,'A careful scientist might eschew?','claims stronger than the evidence supports','checking the evidence','reporting a limitation honestly','避免超出证据支持的结论是谨慎做法。'),Q('eschew',3,1,'Choose the natural construction.','eschew violence','eschew from violence','eschew to violence','eschew 是及物动词，直接接宾语。'),Q('eschew',4,1,'The closest synonym of eschew is?','shun','seek','enrage','shun 意为躲开，与 eschew 接近。')]);
P('escutcheon','escutcheon 源自古法语 escusson，最终来自拉丁语 scutum“盾”；可指纹章盾，也指钥匙孔周围的饰板。',C('escutcheon.s1','家族纹章','The family escutcheon showed a silver heron on a blue field, and the archivist compared it with the seal on an eighteenth-century letter.','家族纹章盾上绘着蓝底银鹭，档案员将它与一封十八世纪信件上的印章作了比较。','The family escutcheon showed a silver heron on a blue field / and the archivist compared it / with the seal on an eighteenth-century letter.','可数名词；纹章义常指承载盾徽图案的盾形面，另有锁孔饰板义。','盾形面上绘有家族纹章，符合 s1。'),M('The herald described the escutcheon as a plain shield with no arms, emblem, or design on it.','The herald described the escutcheon as a shield bearing the family arms and emblem.','描述为毫无图案的空盾与此处纹章盾义不符。'),[Q('escutcheon',1,1,'A heraldic escutcheon is?','a shield or shield-shaped surface bearing a coat of arms','a moving staircase','a layer of skin','escutcheon 的纹章义是承载家徽的盾。'),Q('escutcheon',2,1,'A locksmith may use the word escutcheon for?','a plate fitted around a keyhole','a key’s cutting edge','a person traveling with a minister','锁匠语境中 escutcheon 可指钥匙孔饰板。'),Q('escutcheon',3,1,'The phrase “a blot on one’s escutcheon” refers figuratively to?','a stain on one’s reputation','a clean family record','a metal plate around a door handle','纹章盾可比喻名誉；blot 是污点。'),Q('escutcheon',4,1,'The word’s historical root scutum means?','shield','knowledge','day','escutcheon 的拉丁词源与盾有关。')]);

})();
